```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "private_subnet" {
  vpc_id                  = aws_vpc.main_vpc.id
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = false
}

resource "aws_subnet" "public_subnet" {
  vpc_id                  = aws_vpc.main_vpc.id
  cidr_block              = "10.0.2.0/24"
  map_public_ip_on_launch = true
}

resource "aws_security_group" "internal_sg" {
  vpc_id = aws_vpc.main_vpc.id
  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["10.0.1.0/24"]
  }
}

resource "aws_security_group" "public_sg" {
  vpc_id = aws_vpc.main_vpc.id
  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_instance" "internal_db" {
  instance_class         = "db.t2.micro"
  allocated_storage      = 20
  engine                 = "mysql"
  username               = "admin"
  password               = "password"
  db_subnet_group_name   = "main"
  vpc_security_group_ids = [aws_security_group.internal_sg.id]
  subnet_ids             = [aws_subnet.private_subnet.id]
  skip_final_snapshot    = true
  storage_encrypted      = true
}

resource "aws_db_instance" "public_db" {
  instance_class         = "db.t2.micro"
  allocated_storage      = 20
  engine                 = "mysql"
  username               = "admin"
  password               = "password"
  db_subnet_group_name   = "main"
  vpc_security_group_ids = [aws_security_group.public_sg.id]
  subnet_ids             = [aws_subnet.public_subnet.id]
  skip_final_snapshot    = true
  storage_encrypted      = true
  publicly_accessible    = true
}

resource "aws_route53_zone" "private_zone" {
  name = "private.example.com"
  vpc {
    vpc_id = aws_vpc.main_vpc.id
  }
}

resource "aws_route53_zone" "public_zone" {
  name = "public.example.com"
}

resource "aws_route53_record" "internal_db_record" {
  name    = "db.private.example.com"
  type    = "A"
  zone_id = aws_route53_zone.private_zone.zone_id
  records = [aws_db_instance.internal_db.endpoint]
  ttl     = 300
}

resource "aws_route53_record" "public_db_record" {
  name    = "db.public.example.com"
  type    = "A"
  zone_id = aws_route53_zone.public_zone.zone_id
  records = [aws_db_instance.public_db.endpoint]
  ttl     = 300
}
