  region = "us-west-2"
}

resource "aws_route53_zone" "main_zone" {
  name = "main.example.com"
}

resource "aws_db_instance" "primary_db_instance" {
  instance_class = "db.t3.micro"
  allocated_storage = 20
  engine = "mysql"
  engine_version = "8.0"
  username = "admin"
  password = "password"
}

resource "aws_db_instance" "replica_1_db_instance" {
  instance_class = "db.t3.micro"
  allocated_storage = 20
  engine = "mysql"
  engine_version = "8.0"
  username = "admin"
  password = "password"
  replicate_source_db = aws_db_instance.primary_db_instance.identifier
}

resource "aws_db_instance" "replica_2_db_instance" {
  instance_class = "db.t3.micro"
  allocated_storage = 20
  engine = "mysql"
  engine_version = "8.0"
  username = "admin"
  password = "password"
  replicate_source_db = aws_db_instance.primary_db_instance.identifier
}

resource "aws_route53_record" "weighted_record_primary" {
  zone_id = aws_route53_zone.main_zone.zone_id
  name    = "db.main.example.com"
  type    = "CNAME"
  ttl     = 300

  weighted_routing_policy {
    weight = 100
  }

  records = [aws_db_instance.primary_db_instance.endpoint]
}

resource "aws_route53_record" "weighted_record_replica_1" {
  zone_id = aws_route53_zone.main_zone.zone_id
  name    = "db.main.example.com"
  type    = "CNAME"
  ttl     = 300

  weighted_routing_policy {
    weight = 45
  }

  records = [aws_db_instance.replica_1_db_instance.endpoint]
}

resource "aws_route53_record" "weighted_record_replica_2" {
  zone_id = aws_route53_zone.main_zone.zone_id
  name    = "db.main.example.com"
  type    = "CNAME"
  ttl     = 300

  weighted_routing_policy {
    weight = 45
  }

  records = [aws_db_instance.replica_2_db_instance.endpoint]
}
```

This Terraform configuration sets up a Route 53 hosted zone named "main.example.com" and configures three RDS instances: a primary database and two replicas. It then creates weighted Route 53 records to distribute traffic between these instances based on the specified weights. The primary instance has a weight of 100, while each replica has a weight of 45, ensuring that users are split between the primary and replicas according to the specified policy.

