  username = "admin"
  password = "password"
  db_name = "myapp_db"
}

resource "aws_route53_zone" "myapp_zone" {
  name = "myapp.example.com"
}

resource "aws_route53_record" "blue_record" {
  zone_id = aws_route53_zone.myapp_zone.zone_id
  name    = "blue.myapp.example.com"
  type    = "A"
  ttl     = 300
  records = ["192.168.1.1"]  # Replace with actual IP address or DNS name
}

resource "aws_route53_record" "green_record" {
  zone_id = aws_route53_zone.myapp_zone.zone_id
  name    = "green.myapp.example.com"
  type    = "A"
  ttl     = 300
  records = ["192.168.1.2"]  # Replace with actual IP address or DNS name
}

resource "aws_route53_health_check" "blue_health_check" {
  type                = "HTTP"
  fully_qualified_domain_name = aws_route53_record.blue_record.name
  port                = 80
  resource_path       = "/"
  failure_threshold   = 3
  request_interval    = 30
}

resource "aws_route53_health_check" "green_health_check" {
  type                = "HTTP"
  fully_qualified_domain_name = aws_route53_record.green_record.name
  port                = 80
  resource_path       = "/"
  failure_threshold   = 3
  request_interval    = 30
}

resource "aws_route53_record" "failover_record" {
  zone_id = aws_route53_zone.myapp_zone.zone_id
  name    = "myapp.example.com"
  type    = "A"
  ttl     = 300

  failover_routing_policy {
    type = "PRIMARY"
  }

  health_check_id = aws_route53_health_check.blue_health_check.id

  records = ["192.168.1.1"]  # Replace with actual IP address or DNS name

  depends_on = [
    aws_route53_health_check.blue_health_check,
    aws_route53_health_check.green_health_check
