### Description
This Terraform program creates an Elastic Beanstalk application with an application version lifecycle. The lifecycle configuration retains the version for 5 days before deleting it. The necessary IAM role and policy are also created to manage the lifecycle operations.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "beanstalk_service_role" {
  name = "beanstalk-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "beanstalk_service_policy" {
  name = "beanstalk-service-policy"
  role = aws_iam_role.beanstalk_service_role.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:DeleteObject",
          "elasticbeanstalk:CreateStorageLocation",
          "elasticbeanstalk:Describe*",
          "elasticbeanstalk:Update*",
          "elasticbeanstalk:TerminateEnvironment",
          "elasticbeanstalk:DeleteApplicationVersion"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_elastic_beanstalk_application" "my_elastic_beanstalk_app" {
  name = "my-elastic-beanstalk-app"

  appversion_lifecycle {
    service_role     = aws_iam_role.beanstalk_service_role.arn
    max_age_in_days  = 5
    delete_source_from_s3 = true
  }
}
```

This configuration sets up an Elastic Beanstalk application named `my-elastic-beanstalk-app` with a lifecycle policy that retains application versions for 5 days before deleting them. The necessary IAM role and policy are created to allow Elastic Beanstalk to perform these operations.

