### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for CodeBuild
resource "aws_iam_role" "codebuild_iam_role" {
  name = "codebuild-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })

  inline_policy {
    name = "codebuild-policy"
    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Action = [
            "logs:CreateLogGroup",
            "logs:CreateLogStream",
            "logs:PutLogEvents",
            "s3:GetObject",
            "s3:PutObject",
            "ec2:CreateNetworkInterface",
            "ec2:DescribeDhcpOptions",
            "ec2:DescribeNetworkInterfaces",
            "ec2:DeleteNetworkInterface",
            "ec2:DescribeSubnets",
            "ec2:DescribeSecurityGroups",
            "ec2:DescribeVpcs"
          ]
          Effect = "Allow"
          Resource = "*"
        }
      ]
    })
  }
}

# CodeBuild Project
resource "aws_codebuild_project" "example_codebuild_project" {
  name         = "example-codebuild-project"
  service_role = aws_iam_role.codebuild_iam_role.arn

  source {
    type            = "GITHUB"
    location        = "https://github.com/example/repo.git"
    auth {
      type     = "OAUTH"
      resource = "arn:aws:codebuild:us-west-2:123456789012:project/example-codebuild-project"
    }
  }

  artifacts {
    type = "S3"
    location = "example-artifacts-bucket"
  }

  cache {
    type  = "S3"
    location = "example-cache-bucket"
    modes = ["LOCAL_SOURCE_CACHE", "LOCAL_DOCKER_LAYER_CACHE"]
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "aws/codebuild/amazonlinux2-x86_64-standard:3.0"
    type         = "LINUX_CONTAINER"
  }
}
```

