          Resource = "*"
        }
      ]
    })
  }
}

resource "aws_codebuild_project" "example_codebuild_project" {
  name         = "example-codebuild-project"
  service_role = aws_iam_role.codebuild_iam_role.arn

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "aws/codebuild/amazonlinux2-x86_64-standard:3.0"
    type         = "LINUX_CONTAINER"
  }

  source {
    type     = "GITHUB"
    location = "https://github.com/example/repo.git"
    git_clone_depth = 1
  }

  artifacts {
    type = "S3"
    location = "my-artifacts-bucket"
  }

  secondary_sources {
    source_identifier = "secondary-source"
    type              = "GITHUB"
    location          = "https://github.com/example/secondary-repo.git"
    git_clone_depth   = 1
  }

  secondary_artifacts {
    artifact_identifier = "secondary-artifact"
    type                = "S3"
    location            = "my-secondary-artifacts-bucket"
  }

  environment_variable {
    name  = "EXAMPLE_VAR"
    value = "example-value"
  }
}
```

This Terraform configuration sets up an AWS CodeBuild project with an associated IAM role. The CodeBuild project includes primary and secondary sources, primary and secondary artifacts, and environment variables. The IAM role is configured with the necessary permissions for CodeBuild operations.

