This Terraform program creates an AWS Lex bot named "OrderPizzasBot" for ordering pizzas. It also creates an intent named "OrderPizzasIntent" that the bot will use. The `nlu_intent_confidence_threshold` is set to 0.5, meaning the bot will only consider intents with a confidence level of 0.5 or higher.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_lex_intent" "order_pizzas_intent" {
  name        = "OrderPizzasIntent"
  description = "Intent to order pizzas"

  sample_utterances = [
    "I want to order a pizza",
    "Can I order a pizza?",
    "Order a pizza please"
  ]

  fulfillment_activity {
    type = "ReturnIntent"
  }

  slot {
    name                = "PizzaType"
    slot_type           = "AMAZON.FoodItem"
    slot_constraint     = "Required"
    slot_type_version   = "$$LATEST"
    priority            = 1
    sample_utterances   = ["Margherita", "Pepperoni", "Veggie"]
    slot_constraint     = "Required"
    slot_type           = "AMAZON.FoodItem"
    slot_type_version   = "$$LATEST"
    value_elicitation_prompt {
      max_attempts = 2
      message {
        content     = "What type of pizza would you like?"
        content_type = "PlainText"
      }
    }
  }

  slot {
    name                = "Quantity"
    slot_type           = "AMAZON.NUMBER"
    slot_constraint     = "Required"
    slot_type_version   = "$$LATEST"
    priority            = 2
    sample_utterances   = ["One", "Two", "Three"]
    slot_constraint     = "Required"
    slot_type           = "AMAZON.NUMBER"
    slot_type_version   = "$$LATEST"
    value_elicitation_prompt {
      max_attempts = 2
      message {
        content     = "How many pizzas would you like?"
        content_type = "PlainText"
      }
    }
  }
}

resource "aws_lex_bot" "order_pizzas_bot" {
  name                    = "OrderPizzasBot"
  child_directed          = false
  locale                  = "en-US"
  nlu_intent_confidence_threshold = 0.5

  intent {
    intent_name     = aws_lex_intent.order_pizzas_intent.name
    intent_version  = "$LATEST"
  }

  clarification_prompt {
    max_attempts = 2
    message {
      content     = "I didn't understand that. Can you please repeat?"
      content_type = "PlainText"
    }
  }

  abort_statement {
    message {
      content     = "Sorry, I can't help with that."
      content_type = "PlainText"
    }
  }
}
```

