### Description
This Terraform program sets up a Kinesis Firehose Delivery Stream with an OpenSearch destination. It includes the following components:
1. **AWS Kinesis Stream**: Acts as the source for the Firehose delivery stream.
2. **AWS IAM Role**: Provides necessary permissions for Firehose to access OpenSearch and S3.
3. **AWS IAM Role Policy**: Attaches a policy to the IAM role to grant the required permissions.
4. **AWS S3 Bucket**: Used as a backup location for data that fails to deliver to OpenSearch.
5. **AWS Kinesis Firehose Delivery Stream**: Configured to consume data from the Kinesis stream and deliver it to OpenSearch.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_kinesis_stream" "kinesis_stream" {
  name        = "my-kinesis-stream"
  shard_count = 1
}

resource "aws_iam_role" "firehose_role" {
  name = "firehose-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "firehose_policy" {
  name = "firehose-policy"
  role = aws_iam_role.firehose_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "es:ESHttpPut",
          "es:ESHttpGet",
          "s3:AbortMultipartUpload",
          "s3:GetBucketLocation",
          "s3:GetObject",
          "s3:ListBucket",
          "s3:ListBucketMultipartUploads",
          "s3:PutObject"
        ]
        Effect = "Allow"
        Resource = [
          "arn:aws:es:us-west-2:123456789012:domain/my-opensearch-domain/*",
          "arn:aws:s3:::my-backup-bucket",
          "arn:aws:s3:::my-backup-bucket/*"
        ]
      }
    ]
  })
}

resource "aws_s3_bucket" "s3_bucket" {
  bucket = "my-backup-bucket"
  acl    = "private"
}

resource "aws_kinesis_firehose_delivery_stream" "firehose_delivery_stream" {
  name       = "my-firehose-delivery-stream"
  destination = "opensearch"

  opensearch_configuration {
    domain_arn = "arn:aws:es:us-west-2:123456789012:domain/my-opensearch-domain"
    role_arn   = aws_iam_role.firehose_role.arn
    index_name = "my-index"
    buffering_interval = 300
    buffering_size = 5
    s3_backup_mode = "FailedDataOnly"
    s3_configuration {
      role_arn = aws_iam_role.firehose_role.arn
      bucket_arn = aws_s3_bucket.s3_bucket.arn
      buffering_interval = 300
      buffering_size = 5
      compression_format = "UNCOMPRESSED"
    }
  }

  kinesis_source_configuration {
    kinesis_stream_arn = aws_kinesis_stream.kinesis_stream.arn
    role_arn           = aws_iam_role.firehose_role.arn
  }
}
```

### Explanation
- **Provider Configuration**: Sets the AWS region to `us-west-2`.
- **Kinesis Stream**: Creates a Kinesis stream named `my-kinesis-stream` with 1 shard.
- **IAM Role**: Creates an IAM role named `firehose-role` with a trust policy allowing Firehose to assume the role.
- **IAM Role Policy**: Attaches a policy to the IAM role granting permissions for Firehose to interact with OpenSearch and S3.
- **S3 Bucket**: Creates an S3 bucket named `my-backup-bucket` for backup purposes.
- **Kinesis Firehose Delivery Stream**: Configures a Firehose delivery stream to consume data from the Kinesis stream and deliver it to OpenSearch. It also specifies the S3 backup configuration.

