provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_role" "firehose_role" {
  name = "firehose_delivery_stream_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })

  inline_policy {
    name = "firehose_policy"
    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Action = [
            "s3:AbortMultipartUpload",
            "s3:GetBucketLocation",
            "s3:GetObject",
            "s3:ListBucket",
            "s3:ListBucketMultipartUploads",
            "s3:PutObject"
          ]
          Effect = "Allow"
          Resource = [
            aws_s3_bucket.backup_bucket.arn,
            "${aws_s3_bucket.backup_bucket.arn}/*"
          ]
        },
        {
          Action = [
            "logs:CreateLogDelivery",
            "logs:DescribeLogGroups",
            "logs:DescribeLogStreams",
            "logs:PutLogEvents",
            "logs:PutLogEventsBatch",
            "logs:UpdateLogDelivery"
          ]
          Effect = "Allow"
          Resource = "*"
        }
      ]
    })
  }
}

resource "aws_s3_bucket" "backup_bucket" {
  bucket = "firehose-backup-bucket-${random_string.bucket_suffix.result}"
  acl    = "private"
}

resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
}

resource "aws_kinesis_firehose_delivery_stream" "firehose_delivery_stream" {
  name       = "firehose-delivery-stream"
  destination = "http_endpoint"

  http_endpoint_configuration {
    url              = "https://example.com/firehose"
    name             = "ExampleHTTP"
    buffering_size   = 5
    buffering_interval = 600
    role_arn         = aws_iam_role.firehose_role.arn
    s3_backup_mode   = "FailedDataOnly"

    s3_configuration {
      role_arn = aws_iam_role.firehose_role.arn
      bucket_arn = aws_s3_bucket.backup_bucket.arn
      buffering_size = 5
      buffering_interval = 600
      compression_format = "UNCOMPRESSED"
    }
  }
}
