### Description
This Terraform program creates a Kinesis Firehose Delivery Stream configured with an extended S3 destination. The program includes the necessary IAM roles and policies to ensure that the Firehose Delivery Stream has the required permissions to write to the specified S3 bucket.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "firehose_destination_bucket" {
  bucket = "firehose-destination-bucket-${random_string.suffix.result}"
  acl    = "private"
}

resource "aws_iam_policy_document" "firehose_assume_role_policy" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["firehose.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "firehose_role" {
  name               = "firehose_delivery_stream_role"
  assume_role_policy = data.aws_iam_policy_document.firehose_assume_role_policy.json
}

resource "aws_iam_policy_document" "firehose_s3_access_policy" {
  statement {
    effect = "Allow"
    actions = [
      "s3:AbortMultipartUpload",
      "s3:GetBucketLocation",
      "s3:GetObject",
      "s3:ListBucket",
      "s3:PutObject"
    ]
    resources = [
      aws_s3_bucket.firehose_destination_bucket.arn,
      "${aws_s3_bucket.firehose_destination_bucket.arn}/*"
    ]
  }
}

resource "aws_iam_role_policy_attachment" "firehose_s3_access_policy" {
  policy_arn = aws_iam_policy_document.firehose_s3_access_policy.arn
  role       = aws_iam_role.firehose_role.name
}

resource "aws_kinesis_firehose_delivery_stream" "firehose_delivery_stream" {
  name       = "firehose-delivery-stream"
  destination = "extended_s3"

  extended_s3_configuration {
    role_arn   = aws_iam_role.firehose_role.arn
    bucket_arn = aws_s3_bucket.firehose_destination_bucket.arn
    buffering_interval = 300
    buffering_size     = 5
    compression_format = "UNCOMPRESSED"
    prefix             = "logs/"
    error_output_prefix = "errors/"
  }
}

resource "random_string" "suffix" {
  length  = 8
  special = false
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-east-1` region.
2. **S3 Bucket**: An S3 bucket named `firehose-destination-bucket-${random_string.suffix.result}` is created. The `${random_string.suffix.result}` ensures a unique bucket name.
3. **IAM Policy Document for Assume Role**: A policy document is created to allow the Firehose service to assume the IAM role.
4. **IAM Role**: An IAM role named `firehose_delivery_stream_role` is created with the assume role policy.
5. **IAM Policy Document for S3 Access**: A policy document is created to allow the Firehose role to perform necessary S3 operations on the destination bucket.
6. **IAM Role Policy Attachment**: The S3 access policy is attached to the Firehose role.
7. **Kinesis Firehose Delivery Stream**: A Kinesis Firehose Delivery Stream named `firehose-delivery-stream` is created with an extended S3 destination. The stream is configured to buffer data for 300 seconds or 5 MB before delivering it to the S3 bucket.
8. **Random String**: A random string resource is used to append a suffix to the S3 bucket name to ensure uniqueness.

