This Terraform program sets up a basic Amazon Kinesis Analytics Application with a CloudWatch log stream. It includes the following resources:
1. **AWS CloudWatch Log Group**: A log group to hold the logs.
2. **AWS CloudWatch Log Stream**: A log stream within the log group for the Kinesis Analytics application logs.
3. **AWS Kinesis Stream**: A Kinesis stream that serves as the input for the Kinesis Analytics application.
4. **AWS Kinesis Analytics Application**: The main Kinesis Analytics application configured to use the Kinesis stream and CloudWatch log stream.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_cloudwatch_log_group" "analytics_log_group" {
  name = "kinesis-analytics-log-group"
}

resource "aws_cloudwatch_log_stream" "analytics_log_stream" {
  name           = "kinesis-analytics-log-stream"
  log_group_name = aws_cloudwatch_log_group.analytics_log_group.name
}

resource "aws_kinesis_stream" "analytics_kinesis_stream" {
  name         = "kinesis-analytics-stream"
  shard_count  = 1
}

resource "aws_iam_role" "analytics_role" {
  name = "kinesis-analytics-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kinesisanalytics.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "analytics_policy" {
  name = "kinesis-analytics-policy"
  role = aws_iam_role.analytics_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:PutLogEvents",
          "logs:CreateLogStream",
          "logs:DescribeLogStreams",
          "kinesis:GetRecords",
          "kinesis:GetShardIterator",
          "kinesis:DescribeStream"
        ]
        Effect = "Allow"
        Resource = [
          aws_cloudwatch_log_group.analytics_log_group.arn,
          aws_kinesis_stream.analytics_kinesis_stream.arn
        ]
      }
