    aws_iam_role_policy_attachment.attach_amazon_eks_fargate_pod_execution_policy
  ]
}

resource "aws_eks_fargate_profile" "kube_system_fargate_profile" {
  cluster_name         = aws_eks_cluster.my_eks_cluster.name
  fargate_profile_name = "kube-system-fargate-profile"
  pod_execution_role_arn = aws_iam_role.eks_fargate_pod_execution_role.arn
  subnet_ids           = ["subnet-0123456789abcdef0", "subnet-0fedcba9876543210"]

  selector {
    namespace = "kube-system"
  }

  depends_on = [
    aws_eks_cluster.my_eks_cluster,
    aws_iam_role_policy_attachment.attach_amazon_eks_fargate_pod_execution_policy
  ]
}

resource "null_resource" "patch_coredns_deployment" {
  provisioner "local-exec" {
    command = <<EOT
kubectl --server=${aws_eks_cluster.my_eks_cluster.endpoint} \
        --certificate-authority=${base64decode(aws_eks_cluster.my_eks_cluster.certificate_authority[0].data)} \
        --token=${data.aws_eks_cluster_auth.my_eks_cluster.token} \
        patch deployment coredns -n kube-system -p '{"spec":{"template":{"metadata":{"annotations":{"kubectl.kubernetes.io/restartedAt":"'$(date +%s)'"}}}}}'
EOT
  }

  depends_on = [
    aws_eks_cluster.my_eks_cluster
  ]
}

data "aws_eks_cluster_auth" "my_eks_cluster" {
  name = aws_eks_cluster.my_eks_cluster.name
}
```

