```hcl
provider "aws" {
  region = "us-west-2"
}

variable "bucket_suffix" {
  description = "Suffix to append to the bucket names"
  default     = "test"
}

resource "aws_s3_bucket" "cloudgoat_data_storage" {
  bucket = "cloudgoat-data-storage-${var.bucket_suffix}"
  acl    = "private"
}

resource "aws_s3_bucket_ownership_controls" "cloudgoat_data_storage_ownership" {
  bucket = aws_s3_bucket.cloudgoat_data_storage.id

  rule {
    object_ownership = "ObjectWriter"
  }
}

resource "aws_s3_bucket" "web_data_storage" {
  bucket = "web-data-storage-${var.bucket_suffix}"
  acl    = "private"
}

resource "aws_s3_bucket_object" "web_data_storage_order_data2_csv" {
  bucket = aws_s3_bucket.web_data_storage.id
  key    = "order_data2.csv"
  source = "./path/to/order_data2.csv"
  acl    = "public-read"
}

resource "aws_s3_bucket_public_access_block" "web_data_storage_public_access_block" {
  bucket               = aws_s3_bucket.web_data_storage.id
  block_public_acls    = true
  block_public_policy  = true
  ignore_public_acls   = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "web_data_storage_bucket_policy" {
  bucket = aws_s3_bucket.web_data_storage.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = "*"
        Action = "s3:PutObject"
        Resource = "${aws_s3_bucket.web_data_storage.arn}/*"
      }
    ]
  })
}
```

This Terraform configuration creates two S3 buckets: one for CloudGoat data storage and another for web data storage. The web data storage bucket has public access block settings configured to ignore public ACLs, block public ACLs, and restrict public buckets. Additionally, a bucket policy is created to allow the `s3:PutObject` action for all principals on the web data bucket's objects. The `order_data2.csv` file is uploaded to the web data storage bucket from a specified local file path.

