### Description of the Terraform Program

This Terraform program creates a single-node Amazon Redshift cluster and sets up a scheduled snapshot every 12 hours using AWS Lambda and EventBridge. The program includes the following components:

1. **AWS Provider Configuration**: Configures the AWS provider with a specific region.
2. **IAM Role for Redshift**: Creates an IAM role with the necessary permissions for Redshift.
3. **Redshift Cluster**: Creates a single-node Redshift cluster with basic configurations.
4. **Lambda Function**: Creates a Lambda function that triggers a Redshift snapshot.
5. **EventBridge Rule**: Sets up an EventBridge rule to trigger the Lambda function every 12 hours.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for Redshift
resource "aws_iam_role" "redshift_role" {
  name = "redshift-snapshot-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for Redshift Snapshot
resource "aws_iam_policy" "redshift_snapshot_policy" {
  name        = "redshift-snapshot-policy"
  description = "Policy for Redshift snapshot operations"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "redshift:CreateClusterSnapshot",
          "redshift:DescribeClusters",
          "redshift:DescribeSnapshots"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach the policy to the role
resource "aws_iam_role_policy_attachment" "redshift_policy_attachment" {
  policy_arn = aws_iam_policy.redshift_snapshot_policy.arn
  role       = aws_iam_role.redshift_role.name
}

# Redshift Cluster
resource "aws_redshift_cluster" "redshift_cluster" {
  cluster_identifier = "my-redshift-cluster"
  node_type          = "dc2.large"
  master_username    = "admin"
  master_password    = "SecurePassword123"
  iam_roles          = [aws_iam_role.redshift_role.arn]
}

# Lambda Function to Trigger Redshift Snapshot
resource "aws_lambda_function" "redshift_snapshot_lambda" {
  filename         = "lambda_function_payload.zip"
  function_name    = "redshift-snapshot-lambda"
  role             = aws_iam_role.lambda_execution_role.arn
  handler          = "index.handler"
  runtime          = "python3.8"

  environment {
    variables = {
      CLUSTER_IDENTIFIER = aws_redshift_cluster.redshift_cluster.cluster_identifier
    }
  }
}

# IAM Role for Lambda Execution
resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for Lambda Execution
resource "aws_iam_policy" "lambda_policy" {
  name        = "lambda-policy"
  description = "Policy for Lambda execution"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "redshift:CreateClusterSnapshot"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach the policy to the Lambda execution role
resource "aws_iam_role_policy_attachment" "lambda_policy_attachment" {
  policy_arn = aws_iam_policy.lambda_policy.arn
  role       = aws_iam_role.lambda_execution_role.name
}

# EventBridge Rule to Trigger Lambda Every 12 Hours
resource "aws_cloudwatch_event_rule" "redshift_snapshot_rule" {
  name                = "redshift-snapshot-rule"
  schedule_expression = "cron(0 */12 * * ? *)"
}

# Permission for EventBridge to Invoke Lambda
resource "aws_lambda_permission" "redshift_snapshot_permission" {
  statement_id  = "AllowExecutionFromCloudWatch"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.redshift_snapshot_lambda.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.redshift_snapshot_rule.arn
}

# Target for EventBridge Rule to Invoke Lambda
resource "aws_cloudwatch_event_target" "redshift_snapshot_target" {
  rule      = aws_cloudwatch_event_rule.redshift_snapshot_rule.name
  target_id = "TriggerRedshiftSnapshot"
  arn       = aws_lambda_function.redshift_snapshot_lambda.arn
}
```

### Notes

- **IAM Roles and Policies**: The IAM roles and policies ensure that the Redshift cluster and Lambda function have the necessary permissions to create snapshots and execute the Lambda function.
- **Lambda Function**: The Lambda function is assumed to be a Python script that triggers a Redshift snapshot. The actual implementation of the Lambda function (`lambda_function_payload.zip`) is not provided here.
- **EventBridge Rule**: The EventBridge rule is set to trigger the Lambda function every 12 hours using a cron expression.

