provider "aws" {
  region = "us-east-1"
}

variable "cluster_identifier_primary" {
  description = "Identifier for the primary Redshift cluster"
  default     = "primary-redshift-cluster"
}

variable "cluster_identifier_secondary" {
  description = "Identifier for the secondary Redshift cluster"
  default     = "secondary-redshift-cluster"
}

variable "node_type" {
  description = "Node type for the Redshift clusters"
  default     = "dc2.large"
}

variable "database_name" {
  description = "Database name for the Redshift clusters"
  default     = "mydatabase"
}

variable "master_username" {
  description = "Master username for the Redshift clusters"
  default     = "admin"
}

variable "master_password" {
  description = "Master password for the Redshift clusters"
  default     = "SecurePassword123!"
}

variable "bucket_name" {
  description = "S3 bucket name for logging"
  default     = "redshift-logs-bucket"
}

resource "aws_s3_bucket" "redshift_logs" {
  bucket = var.bucket_name
  acl    = "log-delivery-write"
}

resource "aws_iam_role" "redshift_replication_role" {
  name = "redshift-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "redshift_replication_policy" {
  name        = "redshift-replication-policy"
  description = "Policy for Redshift replication"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:s3:::${aws_s3_bucket.redshift_logs.bucket}/*"
      },
      {
        Action = [
          "redshift:CreateSnapshotCopyGrant",
          "redshift:DescribeSnapshotCopyGrants",
          "redshift:DeleteSnapshotCopyGrant"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "redshift_replication_policy_attachment" {
  role       = aws_iam_role.redshift_replication_role.name
  policy_arn = aws_iam_policy.redshift_replication_policy.arn
}

resource "aws_redshift_cluster" "primary_redshift_cluster" {
  cluster_identifier = var.cluster_identifier_primary
  node_type          = var.node_type
  database_name      = var.database_name
  master_username    = var.master_username
  master_password    = var.master_password

  logging {
    enable      = true
    bucket_name = aws_s3_bucket.redshift_logs.bucket
  }
}

resource "aws_redshift_cluster" "secondary_redshift_cluster" {
  cluster_identifier = var.cluster_identifier_secondary
  node_type          = var.node_type
  database_name      = var.database_name
  master_username    = var.master_username
  master_password    = var.master_password
  cluster_type       = "multi-node"

  snapshot_copy {
    destination_region = "us-east-2"
    grant_name         = "redshift-replication-grant"
  }

  depends_on = [aws_redshift_cluster.primary_redshift_cluster]
}
```

This Terraform configuration sets up the primary Redshift cluster in `us-east-1` and the secondary Redshift cluster in `us-east-2`. The secondary cluster is configured to replicate data from the primary cluster using a snapshot copy grant. The necessary IAM roles and policies are created to manage access between the clusters.

