### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
  role       = aws_iam_role.lambda_execution_role.name
}

resource "aws_lambda_function" "lambda_function" {
  function_name = "dynamodb_lambda_function"
  role          = aws_iam_role.lambda_execution_role.arn
  handler       = "index.handler"
  runtime       = "python3.8"
  filename      = "function.zip"
}

resource "aws_dynamodb_table" "dynamodb_table" {
  name           = "dynamodb_table"
  billing_mode   = "PAY_PER_REQUEST"
  hash_key       = "id"

  attribute {
    name = "id"
    type = "S"
  }

  stream_enabled   = true
  stream_view_type = "NEW_AND_OLD_IMAGES"
}

resource "aws_lambda_event_source_mapping" "lambda_event_source_mapping" {
  function_name = aws_lambda_function.lambda_function.function_name
  event_source_arn = aws_dynamodb_table.dynamodb_table.stream_arn
  starting_position = "LATEST"
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **IAM Role**: An IAM role named `lambda_execution_role` is created with a trust policy allowing Lambda to assume the role.
3. **IAM Role Policy Attachment**: The `AWSLambdaBasicExecutionRole` policy is attached to the IAM role to allow basic execution permissions.
4. **Lambda Function**: A Lambda function named `dynamodb_lambda_function` is created with the specified role, handler, runtime, and filename.
5. **DynamoDB Table**: A DynamoDB table named `dynamodb_table` is created with a single attribute `id` and streaming enabled.
