### Description
This Terraform program creates two AWS EC2 instances in private subnets and shares an EFS file system between them. The EFS file system is configured with a policy that allows the EC2 instances to mount and write to the file system. The program also includes necessary IAM roles and security groups to ensure proper access.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "instance_type" {
  description = "EC2 instance type"
  default     = "t3.micro"
}

variable "ami_id" {
  description = "AMI ID for the EC2 instances"
  default     = "ami-0c55b159cbfafe1f0" # Example AMI ID for us-west-2
}

variable "key_name" {
  description = "Key pair name for SSH access"
  default     = "my-key-pair"
}

variable "vpc_id" {
  description = "VPC ID where the subnets are located"
  default     = "vpc-12345678"
}

variable "private_subnet_ids" {
  description = "List of private subnet IDs"
  type        = list(string)
  default     = ["subnet-12345678", "subnet-87654321"]
}

resource "aws_efs_file_system" "efs_file_system" {
  creation_token = "my-efs-file-system"
  encrypted      = true
}

resource "aws_efs_file_system_policy" "efs_file_system_policy" {
  file_system_id = aws_efs_file_system.efs_file_system.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Principal = "*"
        Action   = [
          "elasticfilesystem:ClientMount",
          "elasticfilesystem:ClientWrite"
        ]
        Resource = aws_efs_file_system.efs_file_system.arn
      }
    ]
  })
}

resource "aws_security_group" "ec2_sg" {
  vpc_id = var.vpc_id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"] # For SSH access, replace with specific IPs
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_instance" "ec2_instance_1" {
  ami           = var.ami_id
  instance_type = var.instance_type
  key_name      = var.key_name
  subnet_id     = element(var.private_subnet_ids, 0)
  security_groups = [aws_security_group.ec2_sg.name]

  connection {
    type        = "ssh"
    user        = "ec2-user"
    private_key = file("~/.ssh/${var.key_name}.pem")
    host        = self.public_ip
  }

  provisioner "remote-exec" {
    inline = [
      "sudo yum install -y amazon-efs-utils",
      "sudo mkdir /mnt/efs",
      "sudo mount -t efs ${aws_efs_file_system.efs_file_system.dns_name}:/ /mnt/efs"
    ]
  }
}

resource "aws_instance" "ec2_instance_2" {
  ami           = var.ami_id
  instance_type = var.instance_type
  key_name      = var.key_name
  subnet_id     = element(var.private_subnet_ids, 1)
  security_groups = [aws_security_group.ec2_sg.name]

  connection {
    type        = "ssh"
    user        = "ec2-user"
    private_key = file("~/.ssh/${var.key_name}.pem")
    host        = self.public_ip
  }

  provisioner "remote-exec" {
    inline = [
      "sudo yum install -y amazon-efs-utils",
      "sudo mkdir /mnt/efs",
      "sudo mount -t efs ${aws_efs_file_system.efs_file_system.dns_name}:/ /mnt/efs"
    ]
  }
}
```

### Explanation
- **Provider Configuration**: Configures the AWS provider with the region `us-west-2`.
- **Variables**: Defines variables for instance type, AMI ID, key pair name, VPC ID, and private subnet IDs with default values.
- **EFS File System**: Creates an EFS file system with encryption enabled.
- **EFS File System Policy**: Sets a policy to allow all principals to mount and write to the EFS file system.
- **Security Group**: Creates a security group to allow SSH access and unrestricted egress.
- **EC2 Instances**: Launches two EC2 instances in the specified private subnets, attaches the security group, and mounts the EFS file system using a remote-exec provisioner.

