### Description

This Terraform program creates a managed Amazon MSK (Managed Streaming for Apache Kafka) cluster with 3 broker nodes in the `us-east-1` region. The configuration includes the necessary nested blocks for specifying the broker node group information, including the instance type, client subnets, and security groups. Additionally, it sets up basic encryption in transit settings.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_vpc" "vpc" {
  cidr_block = "10.0.0.0/16"
}

data "aws_availability_zones" "azs" {
  state = "available"
}

resource "aws_subnet" "subnet_az1" {
  availability_zone = data.aws_availability_zones.azs.names[0]
  cidr_block        = "10.0.1.0/24"
  vpc_id            = aws_vpc.vpc.id
}

resource "aws_subnet" "subnet_az2" {
  availability_zone = data.aws_availability_zones.azs.names[1]
  cidr_block        = "10.0.2.0/24"
  vpc_id            = aws_vpc.vpc.id
}

resource "aws_subnet" "subnet_az3" {
  availability_zone = data.aws_availability_zones.azs.names[2]
  cidr_block        = "10.0.3.0/24"
  vpc_id            = aws_vpc.vpc.id
}

resource "aws_security_group" "sg" {
  vpc_id = aws_vpc.vpc.id

  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_msk_cluster" "managed_msk_cluster" {
  cluster_name           = "my-msk-cluster"
  kafka_version          = "2.8.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = [
      aws_subnet.subnet_az1.id,
      aws_subnet.subnet_az2.id,
      aws_subnet.subnet_az3.id,
    ]
    instance_type = "kafka.m5.large"
    security_groups = [
      aws_security_group.sg.id,
    ]
    az_distribution = "DEFAULT"
  }

  encryption_info {
    encryption_in_transit {
      client_broker = "TLS_PLAINTEXT"
      in_cluster    = true
    }
  }

  tags = {
    Name = "MyMSKCluster"
  }
}
```

### Explanation

1. **Provider Configuration**: The AWS provider is configured to use the `us-east-1` region.
2. **VPC and Subnets**: A VPC is created with three subnets in different availability zones.
3. **Security Group**: A security group is created to allow inbound traffic on port 9092 (Kafka default port) from any IP address.
4. **MSK Cluster**: The MSK cluster is created with the specified configuration:
   - **Cluster Name**: `my-msk-cluster`
   - **Kafka Version**: `2.8.0`
   - **Number of Broker Nodes**: `3`
   - **Broker Node Group Info**: Specifies the subnets, instance type, and security groups.
   - **Encryption Info**: Enables encryption in transit with TLS_PLAINTEXT for client-broker communication and in-cluster communication.

This configuration ensures that the MSK cluster is properly set up with the required resources and configurations.

