### Description
The Terraform program below creates a managed Amazon Managed Streaming for Apache Kafka (MSK) cluster with encryption at rest. The cluster is configured with a specified number of broker nodes, Kafka version, and encryption settings using a KMS key. The program also sets up the necessary VPC and security group configurations required for the MSK cluster.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "cluster_name" {
  description = "The name of the MSK cluster"
  default     = "my-msk-cluster"
}

variable "kafka_version" {
  description = "The Kafka version to use"
  default     = "2.8.1"
}

variable "number_of_broker_nodes" {
  description = "The number of broker nodes in the cluster"
  default     = 3
}

variable "instance_type" {
  description = "The instance type for the broker nodes"
  default     = "m5.large"
}

variable "client_subnets" {
  description = "A list of subnets to connect to in the client VPC"
  type        = list(string)
  default     = ["subnet-0123456789abcdef0", "subnet-0fedcba9876543210", "subnet-01a2b3c4d5e6f7g8h"]
}

variable "security_groups" {
  description = "A list of security groups to associate with the elastic network interfaces"
  type        = list(string)
  default     = ["sg-0123456789abcdef0"]
}

variable "encryption_at_rest_kms_key_arn" {
  description = "The KMS key ARN for encryption at rest"
  default     = "arn:aws:kms:us-west-2:123456789012:key/abcd1234-abcd-1234-abcd-1234abcd1234"
}

resource "aws_vpc" "vpc" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "subnet" {
  count             = length(var.client_subnets)
  vpc_id            = aws_vpc.vpc.id
  cidr_block        = element(var.client_subnets, count.index)
  availability_zone = element(["us-west-2a", "us-west-2b", "us-west-2c"], count.index)
}

resource "aws_security_group" "sg" {
  vpc_id = aws_vpc.vpc.id

  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_msk_cluster" "managed_msk_cluster" {
  cluster_name           = var.cluster_name
  kafka_version          = var.kafka_version
  number_of_broker_nodes = var.number_of_broker_nodes

  broker_node_group_info {
    client_subnets  = var.client_subnets
    instance_type   = var.instance_type
    security_groups = var.security_groups
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = var.encryption_at_rest_kms_key_arn
  }
}
```

### Explanation
- **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
- **Variables**: Several variables are defined with default values to customize the MSK cluster configuration.
- **VPC and Subnets**: A VPC and subnets are created to host the MSK cluster.
- **Security Group**: A security group is configured to allow inbound traffic on port 9092 and outbound traffic to any destination.
- **MSK Cluster**: The `aws_msk_cluster` resource is created with the specified configuration, including encryption at rest using a KMS key.

