### Description of the Terraform Program

This Terraform program creates a managed Amazon MSK (Managed Streaming for Apache Kafka) cluster with JMX Exporter and Node Exporter enabled. The program includes the necessary configurations for the MSK cluster, including the broker node group information, security groups, and subnets. Additionally, it sets up the required IAM roles and policies to allow the JMX Exporter and Node Exporter to function properly.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "cluster_name" {
  description = "The name of the MSK cluster"
  default     = "my-msk-cluster"
}

variable "kafka_version" {
  description = "The desired Kafka software version"
  default     = "2.8.0"
}

variable "number_of_broker_nodes" {
  description = "The desired total number of broker nodes in the Kafka cluster"
  default     = 3
}

variable "instance_type" {
  description = "Specify the instance type to use for the Kafka brokers"
  default     = "kafka.m5.large"
}

variable "client_subnets" {
  description = "A list of subnets to connect to in client VPC"
  type        = list(string)
  default     = ["subnet-0123456789abcdef0", "subnet-0fedcba9876543210", "subnet-01a2b3c4d5e6f7g8h"]
}

variable "security_groups" {
  description = "A list of the security groups to associate with the elastic network interfaces"
  type        = list(string)
  default     = ["sg-0123456789abcdef0"]
}

resource "aws_iam_role" "msk_jmx_exporter_role" {
  name = "${var.cluster_name}-jmx-exporter-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "msk_jmx_exporter_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonMSKJMXExporterPolicy"
  role       = aws_iam_role.msk_jmx_exporter_role.name
}

resource "aws_iam_role" "msk_node_exporter_role" {
  name = "${var.cluster_name}-node-exporter-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "msk_node_exporter_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonMSKNodeExporterPolicy"
  role       = aws_iam_role.msk_node_exporter_role.name
}

resource "aws_msk_cluster" "managed_msk_cluster" {
  cluster_name           = var.cluster_name
  kafka_version          = var.kafka_version
  number_of_broker_nodes = var.number_of_broker_nodes

  broker_node_group_info {
    client_subnets = var.client_subnets
    instance_type  = var.instance_type
    security_groups = var.security_groups
  }

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }
      node_exporter {
        enabled_in_broker = true
      }
    }
  }

  depends_on = [
    aws_iam_role_policy_attachment.msk_jmx_exporter_policy,
    aws_iam_role_policy_attachment.msk_node_exporter_policy
  ]
}
```

### Explanation

1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **Variables**: Several variables are defined with default values to customize the MSK cluster configuration.
3. **IAM Roles and Policies**: Two IAM roles are created for JMX Exporter and Node Exporter, and the necessary policies are attached to these roles.
4. **MSK Cluster**: The `aws_msk_cluster` resource is defined with the required attributes and nested blocks. The `open_monitoring` block enables JMX Exporter and Node Exporter.
5. **Dependencies**: The MSK cluster depends on the IAM role policy attachments to ensure proper initialization.

