### Description
This Terraform program creates a serverless Amazon MSK (Managed Streaming for Apache Kafka) cluster in the `us-east-1` region. The program includes the necessary configuration for the MSK serverless cluster, including client authentication and VPC configuration. The VPC configuration specifies the subnets and security groups required for the cluster.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_vpc" "msk_vpc" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "msk_subnet_az1" {
  vpc_id            = aws_vpc.msk_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-east-1a"
}

resource "aws_subnet" "msk_subnet_az2" {
  vpc_id            = aws_vpc.msk_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-east-1b"
}

resource "aws_security_group" "msk_sg" {
  vpc_id = aws_vpc.msk_vpc.id

  ingress {
    from_port   = 9098
    to_port     = 9098
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "msk_client_role" {
  name = "msk-client-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "msk_client_policy" {
  name        = "msk-client-policy"
  description = "Policy for MSK client authentication"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "kafka:DescribeCluster",
          "kafka:GetBootstrapBrokers",
          "kafka:ListClusters"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "msk_client_policy_attach" {
  role       = aws_iam_role.msk_client_role.name
  policy_arn = aws_iam_policy.msk_client_policy.arn
}

resource "aws_msk_serverless_cluster" "msk_serverless_cluster" {
  cluster_name = "my-msk-serverless-cluster"

  client_authentication {
    sasl {
      iam {
        enabled = true
      }
    }
  }

  vpc_config {
    subnet_ids = [
      aws_subnet.msk_subnet_az1.id,
      aws_subnet.msk_subnet_az2.id
    ]
    security_group_ids = [aws_security_group.msk_sg.id]
  }

  tags = {
    Name = "MyMSKServerlessCluster"
  }
}
```

This Terraform configuration sets up a VPC with two subnets and a security group, creates an IAM role and policy for client authentication, and then defines the MSK serverless cluster with the necessary configurations.

