### Description
This Terraform program creates a serverless MSK (Managed Streaming for Apache Kafka) cluster with 3 broker nodes in the `us-east-1` region. The program includes the necessary configuration for the MSK cluster, including client authentication and VPC configuration. It also sets up an IAM role for the MSK cluster to interact with other AWS services securely.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_role" "msk_serverless_role" {
  name = "msk-serverless-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "msk.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "msk_serverless_policy" {
  name        = "msk-serverless-policy"
  description = "Policy for MSK serverless cluster"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "kafka:DescribeCluster",
          "kafka:GetBootstrapBrokers",
          "kafka:ListClusters",
          "kafka:ListConfigurationRevisions",
          "kafka:ListConfigurations",
          "kafka:ListNodes",
          "kafka:ListScramSecrets",
          "kafka:ListTagsForResource",
          "kafka:TagResource",
          "kafka:UntagResource"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "msk_serverless_policy_attachment" {
  policy_arn = aws_iam_policy.msk_serverless_policy.arn
  role       = aws_iam_role.msk_serverless_role.name
}

resource "aws_vpc" "msk_vpc" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "msk_subnet_1" {
  vpc_id            = aws_vpc.msk_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-east-1a"
}

resource "aws_subnet" "msk_subnet_2" {
  vpc_id            = aws_vpc.msk_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-east-1b"
}

resource "aws_subnet" "msk_subnet_3" {
  vpc_id            = aws_vpc.msk_vpc.id
  cidr_block        = "10.0.3.0/24"
  availability_zone = "us-east-1c"
}

resource "aws_security_group" "msk_sg" {
  vpc_id = aws_vpc.msk_vpc.id

  ingress {
    from_port   = 9098
    to_port     = 9098
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_msk_serverless_cluster" "msk_serverless_cluster" {
  cluster_name = "my-msk-serverless-cluster"

  client_authentication {
    sasl {
      iam {}
    }
  }

  vpc_config {
    subnet_ids         = [aws_subnet.msk_subnet_1.id, aws_subnet.msk_subnet_2.id, aws_subnet.msk_subnet_3.id]
    security_group_ids = [aws_security_group.msk_sg.id]
  }

  tags = {
    Name = "MyMSKServerlessCluster"
  }
}
```

This Terraform configuration sets up the necessary AWS resources to create a serverless MSK cluster with 3 broker nodes in the `us-east-1` region. It includes an IAM role and policy for the MSK cluster, a VPC with subnets and security groups, and the MSK serverless cluster itself.

