### Description of the Terraform Program

This Terraform program creates a serverless MSK (Managed Streaming for Apache Kafka) cluster in the `us-east-2` region. The program includes the following components:

1. **Provider Configuration**: Configures the AWS provider to use the `us-east-2` region.
2. **VPC Configuration**: Creates a VPC, subnets, and a security group to be used by the MSK cluster.
3. **MSK Serverless Cluster**: Defines a serverless MSK cluster with the necessary configurations, including client authentication using IAM.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-2"
}

resource "aws_vpc" "msk_vpc" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "msk_subnet_1" {
  vpc_id            = aws_vpc.msk_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-east-2a"
}

resource "aws_subnet" "msk_subnet_2" {
  vpc_id            = aws_vpc.msk_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-east-2b"
}

resource "aws_security_group" "msk_sg" {
  vpc_id = aws_vpc.msk_vpc.id

  ingress {
    from_port   = 9098
    to_port     = 9098
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_msk_serverless_cluster" "msk_serverless_cluster" {
  cluster_name = "my-msk-serverless-cluster"

  vpc_config {
    subnet_ids       = [aws_subnet.msk_subnet_1.id, aws_subnet.msk_subnet_2.id]
    security_group_ids = [aws_security_group.msk_sg.id]
  }

  client_authentication {
    sasl {
      iam {
        enabled = true
      }
    }
  }
}
```

### Explanation

- **Provider Configuration**: The AWS provider is configured to use the `us-east-2` region.
- **VPC and Subnets**: A VPC with a CIDR block of `10.0.0.0/16` is created. Two subnets are created within this VPC, each in different availability zones (`us-east-2a` and `us-east-2b`).
- **Security Group**: A security group is created to allow inbound traffic on port 9098 (the default port for Kafka) from any IP address. Outbound traffic is allowed to any IP address.
- **MSK Serverless Cluster**: A serverless MSK cluster is created with the specified cluster name. The VPC configuration includes the subnet IDs and security group IDs. Client authentication is configured to use IAM.

This configuration ensures that the MSK serverless cluster is properly set up within the specified VPC and security group, with IAM-based client authentication.

Rego intent:
package main

import future.keywords.in

default allow = false

# Check for MSK Cluster creation
msk_cluster_created(resources) {
some resource in resources
resource.type == "aws_msk_cluster"
resource.change.actions[_] == "create"
}

# Check if the MSK cluster is in us-east-1 (as defined in Terraform)
msk_cluster_region_valid(resource) {
resource.type == "aws_msk_cluster"
input.configuration.provider_config.aws.expressions.region.constant_value == "us-east-1"
}

# Check if the MSK cluster has 3 broker nodes (as defined in Terraform)
broker_node_count_valid(resource) {
resource.type == "aws_msk_cluster"
resource.change.after.number_of_broker_nodes == 3
}

# Check if CloudWatch logging is enabled for broker logs
cloudwatch_logging_enabled(resource) {
resource.type == "aws_msk_cluster"
resource.change.after.logging_info[_].broker_logs[_].cloudwatch_logs[_].enabled == true
}

# Check if S3 logging is enabled for broker logs
s3_logging_enabled(resource) {
resource.type == "aws_msk_cluster"
resource.change.after.logging_info[_].broker_logs[_].s3[_].enabled == true
}

# Check if Kinesis Firehose logging is enabled for broker logs
firehose_logging_enabled(resource) {
resource.type == "aws_msk_cluster"
resource.change.after.logging_info[_].broker_logs[_].firehose[_].enabled == true
}

# Check if encryption at rest is enabled
encryption_at_rest_enabled(resource) {
resource.type == "aws_msk_cluster"
resource.change.after_unknown.encryption_info[_].encryption_at_rest_kms_key_arn
}

# Check if both jmx_exporter and node_exporter are enabled
prometheus_exporters_enabled(resource) {
resource.type == "aws_msk_cluster"
resource.change.after.open_monitoring[_].prometheus[_].jmx_exporter[_].enabled_in_broker == true
resource.change.after.open_monitoring[_].prometheus[_].node_exporter[_].enabled_in_broker == true
}

# Aggregate all checks
allow {
msk_cluster_created(input.resource_changes)
some resource in input.resource_changes
msk_cluster_region_valid(resource)
broker_node_count_valid(resource)
cloudwatch_logging_enabled(resource)
s3_logging_enabled(resource)
firehose_logging_enabled(resource)
encryption_at_rest_enabled(resource)
prometheus_exporters_enabled(resource)
}

