```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_cloudwatch_log_group" "msk_log_group" {
  name = "/aws/msk/my-msk-cluster"
}

resource "aws_s3_bucket" "msk_s3_bucket" {
  bucket = "my-msk-logs-bucket"
  acl    = "private"
}

resource "aws_s3_bucket_server_side_encryption_configuration" "msk_s3_bucket_encryption" {
  bucket = aws_s3_bucket.msk_s3_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_kinesis_firehose_delivery_stream" "msk_firehose_delivery_stream" {
  name       = "my-msk-firehose-delivery-stream"
  destination = "extended_s3"

  extended_s3_configuration {
    role_arn           = aws_iam_role.msk_firehose_role.arn
    bucket_arn         = aws_s3_bucket.msk_s3_bucket.arn
    buffering_interval = 60
    buffering_size     = 5
  }
}

resource "aws_iam_role" "msk_firehose_role" {
  name = "msk_firehose_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "msk_firehose_policy" {
  name = "msk_firehose_policy"
  role = aws_iam_role.msk_firehose_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:AbortMultipartUpload",
          "s3:GetBucketLocation",
          "s3:GetObject",
          "s3:ListBucket",
          "s3:ListBucketMultipartUploads",
          "s3:PutObject"
        ]
        Effect = "Allow"
        Resource = [
          aws_s3_bucket.msk_s3_bucket.arn,
          "${aws_s3_bucket.msk_s3_bucket.arn}/*"
        ]
      }
    ]
  })
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = "my-msk-cluster"
  kafka_version          = "2.8.1"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = ["subnet-12345678", "subnet-87654321"]
    instance_type  = "m5.large"
    security_groups = ["sg-12345678"]
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = "arn:aws:kms:us-west-2:123456789012:key/abcd1234-abcd-1234-abcd-1234abcd1234"
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk_log_group.name
      }
      firehose {
        enabled         = true
        delivery_stream = aws_kinesis_firehose_delivery_stream.msk_firehose_delivery_stream.name
      }
    }
  }

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }
      node_exporter {
        enabled_in_broker = true
      }
    }
  }
}
```

This Terraform configuration sets up an MSK cluster with 3 broker nodes, outputs logs to a CloudWatch log group, and delivers logs to an S3 bucket via a Kinesis Firehose delivery stream. It also ensures encryption at rest for the S3 bucket and enables open monitoring for the MSK cluster.

