### Description
This Terraform program creates an Aurora PostgreSQL cluster with the following components:
- A Virtual Private Cloud (VPC)
- Two subnets within the VPC
- A database subnet group associated with the subnets
- An Internet Gateway attached to the VPC
- A route table for the public subnet
- A security group to allow inbound traffic to the Aurora PostgreSQL cluster
- An IAM role with the necessary policy attached
- An Aurora PostgreSQL cluster
- An instance added to the Aurora PostgreSQL cluster

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create a VPC
resource "aws_vpc" "aurora_postgresql_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

# Create an Internet Gateway
resource "aws_internet_gateway" "aurora_postgresql_igw" {
  vpc_id = aws_vpc.aurora_postgresql_vpc.id
}

# Create a Route Table
resource "aws_route_table" "aurora_postgresql_public_rt" {
  vpc_id = aws_vpc.aurora_postgresql_vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.aurora_postgresql_igw.id
  }
}

# Create Subnets
resource "aws_subnet" "aurora_postgresql_subnet_1" {
  vpc_id            = aws_vpc.aurora_postgresql_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "aurora_postgresql_subnet_2" {
  vpc_id            = aws_vpc.aurora_postgresql_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

# Create a Database Subnet Group
resource "aws_db_subnet_group" "aurora_postgresql_subnet_group" {
  name       = "aurora-postgresql-subnet-group"
  subnet_ids = [aws_subnet.aurora_postgresql_subnet_1.id, aws_subnet.aurora_postgresql_subnet_2.id]
}

# Create a Security Group
resource "aws_security_group" "aurora_postgresql_sg" {
  name        = "aurora-postgresql-sg"
  description = "Allow inbound traffic to Aurora PostgreSQL"
  vpc_id      = aws_vpc.aurora_postgresql_vpc.id
}

# Allow inbound traffic to the Aurora PostgreSQL cluster
resource "aws_security_group_rule" "aurora_postgresql_sg_ingress" {
  type        = "ingress"
  from_port   = 5432
  to_port     = 5432
  protocol    = "tcp"
  cidr_blocks = ["0.0.0.0/0"]
  security_group_id = aws_security_group.aurora_postgresql_sg.id
}

# Create an IAM Role
resource "aws_iam_role" "aurora_postgresql_role" {
  name = "aurora-postgresql-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

# Attach a policy to the IAM role
resource "aws_iam_role_policy_attachment" "aurora_postgresql_role_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSClusterRole"
  role       = aws_iam_role.aurora_postgresql_role.name
}

# Create an Aurora PostgreSQL Cluster
resource "aws_rds_cluster" "aurora_postgresql_cluster" {
  engine              = "aurora-postgresql"
  engine_version      = "13.4"
  cluster_identifier  = "aurora-postgresql-cluster"
  master_username     = "admin"
  master_password     = "password123"
  backup_retention_period = 5
  preferred_backup_window = "07:00-09:00"
  db_subnet_group_name = aws_db_subnet_group.aurora_postgresql_subnet_group.name
  iam_database_authentication_enabled = true
  skip_final_snapshot = true
}

# Add an instance to the Aurora PostgreSQL cluster
resource "aws_rds_cluster_instance" "aurora_postgresql_instance_1" {
  cluster_identifier      = aws_rds_cluster.aurora_postgresql_cluster.cluster_identifier
  instance_class          = "db.t3.medium"
  engine                  = aws_rds_cluster.aurora_postgresql_cluster.engine
  engine_version          = aws_rds_cluster.aurora_postgresql_cluster.engine_version
  db_subnet_group_name    = aws_db_subnet_group.aurora_postgresql_subnet_group.name
  identifier              = "aurora-postgresql-instance-1"
  publicly_accessible     = true
  promotion_tier          = 1
}
```

This Terraform configuration sets up an Aurora PostgreSQL cluster with the necessary networking and security configurations. The cluster and its instance are created with default settings, which can be adjusted as needed.

