### Description
This Terraform program creates a basic DynamoDB table with provisioned billing mode. The table will have a hash key and a range key, and it will include some example attributes. The table will also have a global secondary index (GSI) for additional querying capabilities.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_dynamodb_table" "basic_dynamodb_table" {
  name           = "GameScores"
  billing_mode   = "PROVISIONED"
  read_capacity  = 20
  write_capacity = 20

  hash_key = "UserId"
  range_key = "GameTitle"

  attribute {
    name = "UserId"
    type = "S"
  }

  attribute {
    name = "GameTitle"
    type = "S"
  }

  attribute {
    name = "TopScore"
    type = "N"
  }

  ttl {
    attribute_name = "TimeToExist"
    enabled        = true
  }

  global_secondary_index {
    name               = "GameTitleIndex"
    hash_key           = "GameTitle"
    range_key          = "TopScore"
    write_capacity     = 10
    read_capacity      = 10
    projection_type    = "INCLUDE"
    non_key_attributes = ["UserId"]
  }

  tags = {
    Name        = "dynamodb-table-1"
    Environment = "production"
  }
}
```

This configuration sets up a DynamoDB table named "GameScores" with the specified attributes, billing mode, and global secondary index. The table is configured with a hash key (`UserId`) and a range key (`GameTitle`). The `ttl` block enables time-to-live for items in the table, and the `global_secondary_index` block defines an additional index for efficient querying.

