### Description
This Terraform program creates two AWS Virtual Private Clouds (VPCs) and establishes a peering connection between them. Each VPC has its own route table, and routes are added to these tables to allow traffic between the two VPCs via the peering connection.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_1_cidr_block" {
  description = "CIDR block for VPC 1"
  default     = "10.0.0.0/16"
}

variable "vpc_2_cidr_block" {
  description = "CIDR block for VPC 2"
  default     = "10.1.0.0/16"
}

resource "aws_vpc" "vpc_1" {
  cidr_block           = var.vpc_1_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_vpc" "vpc_2" {
  cidr_block           = var.vpc_2_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_vpc_peering_connection" "vpc_peering_connection" {
  vpc_id      = aws_vpc.vpc_1.id
  peer_vpc_id = aws_vpc.vpc_2.id
  auto_accept = true
}

resource "aws_route_table" "route_table_vpc_1" {
  vpc_id = aws_vpc.vpc_1.id
}

resource "aws_route_table" "route_table_vpc_2" {
  vpc_id = aws_vpc.vpc_2.id
}

resource "aws_route" "route_vpc_1_to_vpc_2" {
  route_table_id         = aws_route_table.route_table_vpc_1.id
  destination_cidr_block = var.vpc_2_cidr_block
  vpc_peering_connection_id = aws_vpc_peering_connection.vpc_peering_connection.id
}

resource "aws_route" "route_vpc_2_to_vpc_1" {
  route_table_id         = aws_route_table.route_table_vpc_2.id
  destination_cidr_block = var.vpc_1_cidr_block
  vpc_peering_connection_id = aws_vpc_peering_connection.vpc_peering_connection.id
}
```

This configuration sets up two VPCs with non-overlapping CIDR blocks, establishes a peering connection between them, and configures route tables to allow traffic between the VPCs. The `auto_accept` attribute is set to `true` to automatically accept the peering connection request.

