```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_chime_voice_connector" "voice_connector_1" {
  name              = "VoiceConnector1"
  require_encryption = true
}

resource "aws_chime_voice_connector" "voice_connector_2" {
  name              = "VoiceConnector2"
  require_encryption = true
}

resource "aws_chime_voice_connector_termination" "termination_1" {
  voice_connector_id = aws_chime_voice_connector.voice_connector_1.id
  calling_regions    = ["US"]
  cidr_allow_list    = ["0.0.0.0/0"]
}

resource "aws_chime_voice_connector_termination" "termination_2" {
  voice_connector_id = aws_chime_voice_connector.voice_connector_2.id
  calling_regions    = ["US"]
  cidr_allow_list    = ["0.0.0.0/0"]
}

resource "aws_chime_voice_connector_origination" "origination_1" {
  voice_connector_id = aws_chime_voice_connector.voice_connector_1.id
  route {
    host     = "example.com"
    priority = 1
    protocol = "TCP"
    weight   = 1
  }
}

resource "aws_chime_voice_connector_origination" "origination_2" {
  voice_connector_id = aws_chime_voice_connector.voice_connector_2.id
  route {
    host     = "example.com"
    priority = 1
    protocol = "TCP"
    weight   = 1
  }
}

resource "aws_chime_voice_connector_group" "voice_connector_group" {
  name = "VoiceConnectorGroup"

  connector {
    priority          = 1
    voice_connector_id = aws_chime_voice_connector.voice_connector_1.id
  }

