### Description
This Terraform program creates an AWS Redshift cluster and configures endpoint access from two specified subnets. The program includes the necessary resources and dependencies as inferred from the prompt.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "cluster_identifier" {
  description = "The identifier for the Redshift cluster"
  default     = "my-redshift-cluster"
}

variable "node_type" {
  description = "The node type for the Redshift cluster"
  default     = "dc2.large"
}

variable "database_name" {
  description = "The name of the database to be created"
  default     = "mydatabase"
}

variable "subnet_group_name" {
  description = "The name of the subnet group"
  default     = "my-subnet-group"
}

variable "subnet1_id" {
  description = "The ID of the first subnet"
  default     = "subnet-0123456789abcdef0"
}

variable "subnet2_id" {
  description = "The ID of the second subnet"
  default     = "subnet-0fedcba9876543210"
}

resource "aws_redshift_cluster" "redshift_cluster" {
  cluster_identifier = var.cluster_identifier
  node_type          = var.node_type
  database_name      = var.database_name
  cluster_subnet_group_name = var.subnet_group_name
  master_username    = "admin"
  master_password    = "SecurePassword123"
}

resource "aws_redshift_endpoint_access" "redshift_endpoint_access_subnet1" {
  cluster_identifier = aws_redshift_cluster.redshift_cluster.cluster_identifier
  endpoint_name      = "${var.cluster_identifier}-endpoint-subnet1"
  subnet_group_name  = var.subnet_group_name
  vpc_security_group_ids = ["sg-0123456789abcdef0"]
}

resource "aws_redshift_endpoint_access" "redshift_endpoint_access_subnet2" {
  cluster_identifier = aws_redshift_cluster.redshift_cluster.cluster_identifier
  endpoint_name      = "${var.cluster_identifier}-endpoint-subnet2"
  subnet_group_name  = var.subnet_group_name
  vpc_security_group_ids = ["sg-0fedcba9876543210"]
}
```

