}

# IAM Role for CodeBuild
resource "aws_iam_role" "codebuild_autograder_role" {
  name = "codebuild-autograder-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for CodeBuild
resource "aws_iam_role_policy" "codebuild_autograder_policy" {
  name = "codebuild-autograder-policy"
  role = aws_iam_role.codebuild_autograder_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Effect = "Allow"
        Resource = [
          aws_s3_bucket.autograder_results_bucket.arn,
          "${aws_s3_bucket.autograder_results_bucket.arn}/*"
        ]
      },
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect = "Allow"
        Resource = "arn:aws:logs:*:*:*"
      }
    ]
  })
}

# S3 Bucket to store results
resource "aws_s3_bucket" "autograder_results_bucket" {
  bucket = "autograder-results-bucket-${random_string.suffix.result}"
  acl    = "private"
}

# S3 Bucket Policy to restrict access
resource "aws_s3_bucket_policy" "autograder_results_bucket_policy" {
  bucket = aws_s3_bucket.autograder_results_bucket.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "s3:*"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.codebuild_autograder_role.arn
        }
        Resource = [
          aws_s3_bucket.autograder_results_bucket.arn,
          "${aws_s3_bucket.autograder_results_bucket.arn}/*"
        ]
      }
    ]
  })
}

# GitHub Credentials for CodeBuild
resource "aws_codebuild_source_credential" "github_credentials" {
  auth_type   = "PERSONAL_ACCESS_TOKEN"
  server_type = "GITHUB"
  token       = var.github_token
}

# CodeBuild Project
resource "aws_codebuild_project" "autograder_project" {
  name         = "autograder-project"
  service_role = aws_iam_role.codebuild_autograder_role.arn

  source {
    type            = "GITHUB"
    location        = "https://github.com/your-repo.git"
    git_clone_depth = 1
    report_build_status = true
  }

  artifacts {
    type = "S3"
    location = aws_s3_bucket.autograder_results_bucket.bucket
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "aws/codebuild/amazonlinux2-x86_64-standard:3.0"
    type         = "LINUX_CONTAINER"
  }
}

# Random String for S3 Bucket Name Uniqueness
resource "random_string" "suffix" {
  length  = 8
  special = false
}
```

### Variables
```hcl
variable "github_token" {
  description = "GitHub personal access token for accessing the repository"
  type        = string
  sensitive   = true
  default     = "your-github-token-here"
}
```

### Notes
- Replace `"your-repo.git"` with the actual GitHub repository URL.
- Replace `"your-github-token-here"` with a valid GitHub personal access token.
- Ensure the IAM policy attached to the role has the necessary permissions for CodeBuild to access the S3 bucket and GitHub repository.
- The S3 bucket policy restricts access to the results bucket to authorized users or roles.

