  name   = "autograder-codebuild-policy"
  role   = aws_iam_role.autograder_codebuild_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Effect = "Allow"
        Resource = [
          "${aws_s3_bucket.autograder_results_bucket.arn}",
          "${aws_s3_bucket.autograder_results_bucket.arn}/*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_codebuild_policy_to_role" {
  policy_arn = aws_iam_role_policy.autograder_codebuild_policy.arn
  role       = aws_iam_role.autograder_codebuild_role.name
}

resource "aws_codebuild_source_credential" "github_credentials" {
  auth_type   = "PERSONAL_ACCESS_TOKEN"
  server_type = "GITHUB"
  token       = var.github_token
}

resource "aws_codebuild_project" "autograder_build_project" {
  name         = "autograder-build-project"
  service_role = aws_iam_role.autograder_codebuild_role.arn

  source {
    type            = "GITHUB"
    location        = "https://github.com/your-repo/your-repo.git"
    git_clone_depth = 1
    report_build_status = true
  }

