### Description
The Terraform program below sets up an isolated environment for an autograder using AWS CodeBuild and AWS VPC. The VPC is configured to prevent the students' code from reaching the internet, ensuring a secure execution environment. The program includes the creation of a VPC, subnets, security groups, and an IAM role for CodeBuild to interact with the VPC.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create a VPC
resource "aws_vpc" "autograder_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "AutograderVPC"
  }
}

# Create a private subnet
resource "aws_subnet" "autograder_subnet" {
  vpc_id            = aws_vpc.autograder_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
  map_public_ip_on_launch = false
  tags = {
    Name = "AutograderSubnet"
  }
}

# Create a security group for the VPC
resource "aws_security_group" "autograder_sg" {
  name        = "AutograderSecurityGroup"
  description = "Security group for the autograder"
  vpc_id      = aws_vpc.autograder_vpc.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]  # Adjust as needed for SSH access
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "AutograderSecurityGroup"
  }
}

# Create an IAM role for CodeBuild
resource "aws_iam_role" "autograder_codebuild_role" {
  name = "AutograderCodeBuildRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })
}

# Attach policies to the IAM role
resource "aws_iam_role_policy_attachment" "autograder_codebuild_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AWSCodeBuildDeveloperAccess"
  role       = aws_iam_role.autograder_codebuild_role.name
}

# Create a CodeBuild project
resource "aws_codebuild_project" "autograder_project" {
  name         = "AutograderProject"
  description  = "CodeBuild project for autograding"
  build_timeout = 60

  source {
    type            = "GITHUB"
    location          = "https://github.com/your-repo/autograder.git"
    git_clone_depth = 1
  }

  artifacts {
    type = "NO_ARTIFACTS"
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/amazonlinux2-x86_64-standard:3.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"
  }

  service_role = aws_iam_role.autograder_codebuild_role.arn

  vpc_config {
    vpc_id             = aws_vpc.autograder_vpc.id
    subnets            = [aws_subnet.autograder_subnet.id]
    security_group_ids = [aws_security_group.autograder_sg.id]
  }

  tags = {
    Name = "AutograderProject"
  }
}
```

This Terraform configuration sets up a VPC with a private subnet and a security group to isolate the autograder environment. It also creates an IAM role for AWS CodeBuild and configures a CodeBuild project to run in the VPC, ensuring that the students' code cannot reach the internet.

