    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "alpine"
    type         = "LINUX_CONTAINER"
  }

  source {
    type         = "GITHUB"
    location     = "github.com/source-location"
    git_clone_depth = 1
  }

  vpc_config {
    vpc_id             = aws_vpc.main_vpc.id
    subnets            = [aws_subnet.main_subnet.id]
    security_group_ids = [aws_security_group.no_internet_access_sg.id]
  }
}

resource "random_string" "suffix" {
  length  = 8
  special = false
}
```

This Terraform configuration sets up an AWS S3 bucket for storing CodeBuild output, a VPC with a subnet, a security group to block internet access, and an AWS CodeBuild project configured to use the S3 bucket and VPC resources. The IAM role and policy are also created to allow the CodeBuild project to perform necessary actions.

