### Description
This Terraform program provisions an AWS EC2 instance, creates an EC2 key pair, sets up an AWS Backup vault, and configures a backup plan to back up the EC2 instance daily at midnight. The configuration ensures that all resources are properly interdependent and correctly referenced.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_key_pair" "my_key_pair" {
  key_name   = "my-key-pair"
  public_key = "ssh-rsa AAAAB3NzaC1yc2EAAAADAQABAAABAQC..."
}

resource "aws_instance" "my_ec2_instance" {
  ami           = "ami-0c55b159cbfafe1f0"  # Example AMI ID for Amazon Linux 2
  instance_type = "t3.micro"
  key_name      = aws_key_pair.my_key_pair.key_name
  tags = {
    Name = "My EC2 Instance"
  }
}

resource "aws_backup_vault" "my_backup_vault" {
  name = "my-backup-vault"
}

resource "aws_backup_plan" "my_backup_plan" {
  name = "my-backup-plan"

