### Description
This Terraform program sets up the infrastructure for a video streaming site using AWS Load Balancing. It includes a VPC, a public subnet, an Application Load Balancer (ALB), a target group, a security group, an IAM role, an instance profile, a launch template, an Auto Scaling Group (ASG), and a listener for the ALB. The setup ensures that the load balancer distributes traffic to multiple EC2 instances managed by the ASG.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "video_streaming_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "video_streaming_subnet_public" {
  vpc_id                  = aws_vpc.video_streaming_vpc.id
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true
  availability_zone       = "us-west-2a"
}

resource "aws_lb" "video_streaming_load_balancer" {
  name            = "video-streaming-lb"
  internal        = false
  load_balancer_type = "application"
  subnets         = [aws_subnet.video_streaming_subnet_public.id]
}

resource "aws_lb_target_group" "video_streaming_target_group" {
  name     = "video-streaming-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.video_streaming_vpc.id
}

resource "aws_security_group" "video_streaming_sg" {
  name        = "video-streaming-sg"
  description = "Allow HTTP traffic"
  vpc_id      = aws_vpc.video_streaming_vpc.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "video_streaming_ec2_role" {
  name = "video-streaming-ec2-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_instance_profile" "video_streaming_instance_profile" {
  name = "video-streaming-instance-profile"
  role = aws_iam_role.video_streaming_ec2_role.name
}

resource "aws_launch_template" "video_streaming_launch_template" {
  name          = "video-streaming-launch-template"
  image_id      = "ami-0c55b159cbfafe1f0"  # Example AMI ID
  instance_type = "t3.micro"

  iam_instance_profile {
    name = aws_iam_instance_profile.video_streaming_instance_profile.name
  }

  network_interfaces {
    associate_public_ip_address = true
  }

  security_group_names = [aws_security_group.video_streaming_sg.name]
}

resource "aws_autoscaling_group" "video_streaming_asg" {
  name                 = "video-streaming-asg"
  launch_template {
    id      = aws_launch_template.video_streaming_launch_template.id
    version = "$Latest"
  }
  target_group_arns = [aws_lb_target_group.video_streaming_target_group.arn]
  vpc_zone_identifier = [aws_subnet.video_streaming_subnet_public.id]

  min_size = 1
  max_size = 3
}

resource "aws_lb_listener" "video_streaming_listener" {
  load_balancer_arn = aws_lb.video_streaming_load_balancer.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.video_streaming_target_group.arn
  }
}
```

