  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_security_group" "my_security_group" {
  vpc_id = aws_vpc.my_vpc.id
  name   = "postgres-sg"

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_parameter_group" "my_postgres_param_group" {
  family = "postgres15"

  parameter {
    name         = "shared_buffers"
    value        = "256MB"
    apply_method = "pending-reboot"
  }
}

resource "aws_kms_key" "my_kms_key" {
  description             = "KMS key for PostgreSQL encryption"
  deletion_window_in_days = 10
}

resource "aws_db_instance" "my_postgres_db" {
  instance_class       = "db.t3.medium"
  allocated_storage    = 50
  engine               = "postgres"
  engine_version       = "15"
  name                 = "mydatabase"
  username             = "admin"
  password             = "securepassword"
  db_subnet_group_name = aws_db_subnet_group.my_db_subnet_group.name
  vpc_security_group_ids = [aws_security_group.my_security_group.id]
  parameter_group_name = aws_db_parameter_group.my_postgres_param_group.name
  kms_key_id           = aws_kms_key.my_kms_key.arn
  multi_az             = true
  storage_encrypted    = true
}

resource "aws_db_subnet_group" "my_db_subnet_group" {
  name       = "my-db-subnet-group"
  subnet_ids = [aws_subnet.my_subnet.id]
}
```

