LLM Output #0:
### Description
This Terraform program sets up a PostgreSQL database instance in AWS within a custom VPC and subnet. It includes the creation of a VPC, a subnet, and a PostgreSQL database instance with specified details such as engine version, instance size, storage, and associated networking resources.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "custom_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "CustomVPC"
  }
}

resource "aws_subnet" "custom_subnet" {
  vpc_id                  = aws_vpc.custom_vpc.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = "us-west-2a"
  map_public_ip_on_launch = true
  tags = {
    Name = "CustomSubnet"
  }
}

resource "aws_db_instance" "postgres_db" {
  engine               = "postgres"
  engine_version       = "13.7"
  instance_class       = "db.t3.micro"
  allocated_storage    = 20
  username             = "admin"
  password             = "securepassword"
  db_subnet_group_name = aws_db_subnet_group.default.name
  vpc_security_group_ids = [aws_security_group.default.id]
  skip_final_snapshot  = true
  tags = {
    Name = "PostgreSQLDB"
  }
}

resource "aws_db_subnet_group" "default" {
  name       = "default-subnet-group"
  subnet_ids = [aws_subnet.custom_subnet.id]
  tags = {
    Name = "DefaultSubnetGroup"
  }
}

resource "aws_security_group" "default" {
  name        = "default-sg"
  description = "Allow PostgreSQL traffic"
  vpc_id      = aws_vpc.custom_vpc.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "DefaultSecurityGroup"
  }
}
```

This configuration creates a VPC, a subnet within that VPC, and a PostgreSQL database instance within the subnet. The database instance is configured with a specific engine version, instance class, and storage. Security groups are set up to allow inbound traffic on port 5432 for PostgreSQL.

