### Description
This Terraform configuration sets up an AWS RDS Aurora MySQL cluster with a proxy for enhanced connection management. It includes the creation of a VPC, subnets, security groups, IAM roles, and a Secrets Manager secret for secure credential storage. The RDS cluster is configured with a final snapshot identifier "snapshot".

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create a VPC
resource "aws_vpc" "aurora_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

# Create subnets
resource "aws_subnet" "aurora_subnet_1" {
  vpc_id            = aws_vpc.aurora_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "aurora_subnet_2" {
  vpc_id            = aws_vpc.aurora_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

# Create a security group
resource "aws_security_group" "aurora_sg" {
  vpc_id = aws_vpc.aurora_vpc.id
  name   = "aurora-sg"

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create an IAM role for the Aurora proxy
resource "aws_iam_role" "aurora_proxy_role" {
  name = "aurora-proxy-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM policy for the Aurora proxy
resource "aws_iam_policy" "aurora_proxy_policy" {
  name        = "aurora-proxy-policy"
  description = "Policy for Aurora proxy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "secretsmanager:GetSecretValue"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach the policy to the role
resource "aws_iam_role_policy_attachment" "attach_aurora_proxy_policy" {
  policy_arn = aws_iam_policy.aurora_proxy_policy.arn
  role       = aws_iam_role.aurora_proxy_role.name
}

# Create a Secrets Manager secret for Aurora credentials
resource "aws_secretsmanager_secret" "aurora_credentials" {
  name = "aurora-credentials"
}

# Create an Aurora MySQL cluster
resource "aws_rds_cluster" "aurora_cluster" {
  engine              = "aurora-mysql"
  engine_version      = "8.0.mysql_aurora.3.02.1"
  cluster_identifier  = "aurora-cluster"
  master_username     = "admin"
  master_password     = "password"
  db_subnet_group_name = aws_db_subnet_group.aurora_subnet_group.name
  vpc_security_group_ids = [aws_security_group.aurora_sg.id]
  iam_roles           = [aws_iam_role.aurora_proxy_role.arn]
  backup_retention_period = 5
  skip_final_snapshot = false
  final_snapshot_identifier = "snapshot"
}

# Create a DB subnet group
resource "aws_db_subnet_group" "aurora_subnet_group" {
  name       = "aurora-subnet-group"
  subnet_ids = [aws_subnet.aurora_subnet_1.id, aws_subnet.aurora_subnet_2.id]
}

# Create an Aurora proxy
resource "aws_db_proxy" "aurora_proxy" {
  name                   = "aurora-proxy"
  engine_family          = "MYSQL"
  role_arn               = aws_iam_role.aurora_proxy_role.arn
  vpc_subnet_ids         = [aws_subnet.aurora_subnet_1.id, aws_subnet.aurora_subnet_2.id]
  vpc_security_group_ids = [aws_security_group.aurora_sg.id]

  auth {
    auth_scheme = "SECRETS"
    secret_arn  = aws_secretsmanager_secret.aurora_credentials.arn
    username    = "admin"
  }
}

# Create a default target group for the Aurora proxy
resource "aws_db_proxy_default_target_group" "aurora_proxy_target_group" {
  db_proxy_name = aws_db_proxy.aurora_proxy.name
}
```

This Terraform configuration sets up the required infrastructure for an AWS RDS Aurora MySQL cluster with a proxy, including VPC, subnets, security groups, IAM roles, and Secrets Manager for secure credential storage. The RDS cluster is configured with a final snapshot identifier "snapshot".

