### Description
This Terraform program sets up an AWS S3 bucket for long-term data storage with various configurations including versioning, lifecycle rules, logging, encryption, and access control. It also creates an IAM role and policy for backup operations.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_s3_bucket" "long_term_data_storage" {
  bucket = "long-term-data-storage-bucket"
  acl    = "private"
  tags = {
    Name        = "LongTermDataStorage"
    Environment = "production"
  }
}

resource "aws_s3_bucket_versioning" "long_term_data_storage_versioning" {
  bucket = aws_s3_bucket.long_term_data_storage.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_iam_role" "s3_backup_role" {
  name = "S3BackupRole"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "s3_backup_policy" {
  name        = "S3BackupPolicy"
  description = "Policy for S3 backup operations"
  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:s3:::${aws_s3_bucket.long_term_data_storage.bucket}/*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_s3_backup_policy_to_role" {
  policy_arn = aws_iam_policy.s3_backup_policy.arn
  role       = aws_iam_role.s3_backup_role.name
}

resource "aws_s3_bucket_lifecycle_configuration" "long_term_data_storage_lifecycle" {
  bucket = aws_s3_bucket.long_term_data_storage.id
  rule {
    id     = "ExpireOldObjects"
    status = "Enabled"
    prefix = ""
    expiration {
      days = 365
    }
  }
}

resource "aws_s3_bucket_logging" "long_term_data_storage_logging" {
  bucket        = aws_s3_bucket.long_term_data_storage.id
  target_bucket = aws_s3_bucket.long_term_data_storage.id
  target_prefix = "logs/"
}

resource "aws_s3_bucket_server_side_encryption_configuration" "long_term_data_storage_encryption" {
  bucket = aws_s3_bucket.long_term_data_storage.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_acl" "long_term_data_storage_acl" {
  bucket = aws_s3_bucket.long_term_data_storage.id
  acl    = "private"
}

resource "aws_s3_bucket_cors_configuration" "long_term_data_storage_cors" {
  bucket = aws_s3_bucket.long_term_data_storage.id
  cors_rule {
    allowed_headers = ["*"]
    allowed_methods = ["GET", "PUT", "POST"]
    allowed_origins = ["*"]
    max_age_seconds = 3000
  }
}

resource "aws_s3_bucket_request_payment_configuration" "long_term_data_storage_request_payment" {
  bucket = aws_s3_bucket.long_term_data_storage.id
  payer  = "BucketOwner"
}

resource "aws_s3_bucket_website_configuration" "long_term_data_storage_website" {
  bucket = aws_s3_bucket.long_term_data_storage.id
  index_document {
    suffix = "index.html"
  }
  error_document {
    key = "error.html"
  }
}
```

This Terraform configuration sets up an S3 bucket with versioning, lifecycle rules, logging, encryption, and access control. It also creates an IAM role and policy for backup operations, ensuring that the bucket is properly configured for long-term data storage and backup.

