### Description

This Terraform script sets up a Network Load Balancer (NLB) attached to an EC2 instance of type `t2.micro`. The script includes the necessary resources such as a VPC, subnets, and security groups to ensure the EC2 instance and NLB are properly configured and can communicate within the same network.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "instance_ami" {
  description = "AMI ID for the EC2 instance"
  default     = "ami-0c55b159cbfafe1f0"  # Example AMI ID for Amazon Linux 2 in us-west-2
}

variable "instance_type" {
  description = "Instance type for the EC2 instance"
  default     = "t2.micro"
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidr_block" {
  description = "CIDR block for the subnet"
  default     = "10.0.1.0/24"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block
  tags = {
    Name = "MainVPC"
  }
}

resource "aws_subnet" "main" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_cidr_block
  availability_zone = "us-west-2a"
  tags = {
    Name = "MainSubnet"
  }
}

resource "aws_security_group" "instance_sg" {
  name        = "InstanceSecurityGroup"
  description = "Allow SSH and HTTP traffic"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_instance" "ec2_instance" {
  ami           = var.instance_ami
  instance_type = var.instance_type
  subnet_id     = aws_subnet.main.id
  vpc_security_group_ids = [aws_security_group.instance_sg.id]

  tags = {
    Name = "MyEC2Instance"
  }
}

resource "aws_lb" "network_load_balancer" {
  name               = "MyNetworkLoadBalancer"
  load_balancer_type = "network"
  subnets            = [aws_subnet.main.id]
  enable_deletion_protection = true

  tags = {
    Name = "MyNetworkLoadBalancer"
  }
}

resource "aws_lb_target_group" "nlb_target_group" {
  name     = "MyNLBTargetGroup"
  port     = 80
  protocol = "TCP"
  vpc_id   = aws_vpc.main.id

  health_check {
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
    path                = "/"
  }
}

resource "aws_lb_listener" "nlb_listener" {
  load_balancer_arn = aws_lb.network_load_balancer.arn
  port              = 80
  protocol          = "TCP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.nlb_target_group.arn
  }
}

resource "aws_lb_target_group_attachment" "nlb_target_attachment" {
  target_group_arn = aws_lb_target_group.nlb_target_group.arn
  target_id        = aws_instance.ec2_instance.id
  port             = 80
}
```

This Terraform script creates a VPC, a subnet, and a security group. It then provisions an EC2 instance within the subnet and associates it with the security group. A Network Load Balancer (NLB) is created and attached to the subnet. A target group is set up to manage the EC2 instance, and a listener is configured to forward traffic to the target group.

