### Description
This Terraform program creates an Application Load Balancer (ALB) that forwards traffic to a Network Load Balancer (NLB). The ALB is configured with a target group that points to the NLB's target group ARN. The ALB is set up to handle HTTP traffic and is associated with specified subnets and security groups.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_lb" "nlb_forwarder" {
  name               = "nlb-forwarder-alb"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb_sg.id]
  subnets            = [for subnet in aws_subnet.public : subnet.id]

  enable_deletion_protection = true

  access_logs {
    bucket = aws_s3_bucket.lb_logs.id
    prefix = "alb-logs/"
    enabled = true
  }

  tags = {
    Environment = "production"
  }
}

resource "aws_lb_target_group" "nlb_target_group" {
  name     = "nlb-target-group"
  port     = 80
  protocol = "TCP"
  vpc_id   = aws_vpc.main.id

  target_type = "ip"

  health_check {
    interval            = 30
    path                = "/"
    protocol            = "HTTP"
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }

  tags = {
    Environment = "production"
  }
}

resource "aws_lb_listener" "nlb_listener" {
  load_balancer_arn = aws_lb.nlb_forwarder.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.nlb_target_group.arn
  }
}

resource "aws_security_group" "alb_sg" {
  name        = "alb-security-group"
  description = "Security group for ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Environment = "production"
  }
}

resource "aws_security_group" "nlb_sg" {
  name        = "nlb-security-group"
  description = "Security group for NLB"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Environment = "production"
  }
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "public-subnet-${count.index}"
  }
}

data "aws_availability_zones" "available" {}

resource "aws_s3_bucket" "lb_logs" {
  bucket = "alb-logs-bucket-${random_string.suffix.result}"
  acl    = "log-delivery-write"

  tags = {
    Environment = "production"
  }
}

resource "random_string" "suffix" {
  length  = 8
  special = false
}
```

### Explanation
- **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
- **Application Load Balancer (ALB)**: An ALB named `nlb-forwarder-alb` is created with the specified subnets and security groups. It has access logs enabled and is tagged for environment tracking.
- **Target Group**: A target group named `nlb-target-group` is created for the NLB, configured to handle TCP traffic on port 80.
- **Listener**: A listener is added to the ALB to forward traffic to the target group.
- **Security Groups**: Security groups are created for both the ALB and the NLB to allow HTTP traffic.
- **VPC and Subnets**: A VPC and two public subnets are created to support the ALB and NLB.
- **S3 Bucket**: An S3 bucket is created to store access logs for the ALB.
- **Random String**: A random string is used to ensure the S3 bucket name is unique.

