### Description
This Terraform program creates an Application Load Balancer (ALB) with a redirect action from HTTP to HTTPS. It includes the following components:

1. **AWS Load Balancer (`aws_lb`)**: An Application Load Balancer that listens on ports 80 and 443.
2. **Subnet Mapping**: The load balancer is attached to specified subnets.
3. **Security Groups**: Security groups are associated with the load balancer to control inbound traffic.
4. **Listeners**:
   - A listener on port 80 that redirects HTTP traffic to HTTPS.
   - A listener on port 443 that forwards HTTPS traffic to a target group.
5. **Target Group (`aws_lb_target_group`)**: A target group that defines the backend instances to which the load balancer routes traffic.
6. **Listener Rules**:
   - A rule on the HTTP listener to redirect traffic to HTTPS.
   - A rule on the HTTPS listener to forward traffic to the target group.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_lb" "my_load_balancer" {
  name               = "my-alb"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.lb_sg.id]
  subnets            = [aws_subnet.public1.id, aws_subnet.public2.id]

  access_logs {
    bucket = aws_s3_bucket.lb_logs.id
    prefix = "alb-logs/"
    enabled = true
  }
}

resource "aws_lb_listener" "listener_80" {
  load_balancer_arn = aws_lb.my_load_balancer.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "redirect"

    redirect {
      protocol         = "HTTPS"
      port             = "443"
      status_code      = "HTTP_301"
    }
  }
}

resource "aws_lb_listener" "listener_443" {
  load_balancer_arn = aws_lb.my_load_balancer.arn
  port              = 443
  protocol          = "HTTPS"
  certificate_arn   = "arn:aws:acm:us-west-2:123456789012:certificate/your-certificate-arn"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.target_group.arn
  }
}

resource "aws_lb_target_group" "target_group" {
  name     = "my-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_subnet.public1.vpc_id

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }
}

resource "aws_lb_listener_rule" "redirect_rule" {
  listener_arn = aws_lb_listener.listener_80.arn
  priority     = 100

  action {
    type = "redirect"

    redirect {
      protocol         = "HTTPS"
      port             = "443"
      status_code      = "HTTP_301"
    }
  }

  condition {
    field  = "http-header"
    host_header {
      values = ["example.com"]
    }
  }
}

resource "aws_lb_listener_rule" "forward_rule" {
  listener_arn = aws_lb_listener.listener_443.arn
  priority     = 100

  action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.target_group.arn
  }

  condition {
    field  = "http-header"
    host_header {
      values = ["example.com"]
    }
  }
}

resource "aws_security_group" "lb_sg" {
  name        = "my-lb-sg"
  description = "Security group for ALB"
  vpc_id      = aws_subnet.public1.vpc_id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_subnet" "public1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "public2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_s3_bucket" "lb_logs" {
  bucket = "my-alb-logs-bucket"
}
```

### Explanation
- **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
- **Load Balancer**: An Application Load Balancer is created with two listeners on ports 80 and 443. The load balancer is associated with specified subnets and security groups.
- **Listeners**: 
  - Port 80 listener has a default action to redirect HTTP traffic to HTTPS.
  - Port 443 listener has a default action to forward HTTPS traffic to the target group.
- **Target Group**: A target group is defined to manage the backend instances.
- **Listener Rules**: 
  - A rule on the HTTP listener to redirect traffic to HTTPS.
  - A rule on the HTTPS listener to forward traffic to the target group.
- **Security Group**: A security group is created to allow inbound traffic on ports 80 and 443.
- **Subnets and VPC**: Subnets and a VPC are created to support the load balancer.
- **S3 Bucket**: An S3 bucket is created to store access logs for the load balancer.

