```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_lb" "my_application_load_balancer" {
  name               = "my-application-load-balancer"
  internal           = false
  load_balancer_type = "application"
  subnets            = ["subnet-0123456789abcdef0", "subnet-0fedcba9876543210"]
  security_groups    = ["sg-0123456789abcdef0"]

  access_logs {
    bucket = "my-load-balancer-logs"
    prefix = "logs/"
    enabled = true
  }

  enable_deletion_protection = true
}

resource "aws_lb_listener" "listener_80" {
  load_balancer_arn = aws_lb.my_application_load_balancer.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "fixed-response"
    fixed_response {
      content_type = "text/plain"
      message_body = "Fixed response content"
      status_code  = "200"
    }
  }
}

resource "aws_lb_listener_rule" "rule_authenticate_cognito" {
  listener_arn = aws_lb_listener.listener_80.arn
  priority     = 100

  action {
    type = "authenticate-cognito"
    authenticate_cognito {
      user_pool_arn       = aws_cognito_user_pool.my_user_pool.arn
      user_pool_client_id = aws_cognito_user_pool_client.my_user_pool_client.id
      user_pool_domain    = "my-user-pool-domain.auth.us-west-2.amazoncognito.com"
    }
  }

  condition {
    field  = "host-header"
    values = ["example.com"]
  }
}

resource "aws_cognito_user_pool" "my_user_pool" {
  name = "my_user_pool"

  admin_create_user_config {
    allow_admin_create_user_only = false
  }

  password_policy {
    minimum_length                = 8
    require_lowercase             = true
    require_numbers               = true
    require_symbols               = true
    require_uppercase             = true
    temporary_password_validity_days = 7
  }
}

resource "aws_cognito_user_pool_client" "my_user_pool_client" {
  name         = "my_user_pool_client"
  user_pool_id = aws_cognito_user_pool.my_user_pool.id

  generate_secret = true
  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                 = ["code", "implicit"]
  allowed_oauth_scopes                  = ["phone", "email", "openid", "profile"]
  callback_urls                       = ["https://example.com/callback"]
  logout_urls                         = ["https://example.com/logout"]
}

resource "aws_cognito_identity_pool" "my_identity_pool" {
  identity_pool_name               = "my_identity_pool"
  allow_unauthenticated_identities = true
  supported_login_providers        = {
    "cognito-idp.us-west-2.amazonaws.com/${aws_cognito_user_pool.my_user_pool.id}" = ""
  }
}

resource "aws_iam_role" "cognito_authenticated_role" {
  name = "cognito_authenticated_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = "cognito-identity.amazonaws.com"
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "cognito-identity.amazonaws.com:aud" = aws_cognito_identity_pool.my_identity_pool.id
          }
          "ForAnyValue:StringLike" = {
            "cognito-identity.amazonaws.com:amr" = "authenticated"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "cognito_authenticated_policy" {
  name = "cognito_authenticated_policy"
  role = aws_iam_role.cognito_authenticated_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "mobileanalytics:PutEvents",
          "cognito-sync:*",
          "cognito-identity:*"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role" "cognito_unauthenticated_role" {
  name = "cognito_unauthenticated_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = "cognito-identity.amazonaws.com"
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "cognito-identity.amazonaws.com:aud" = aws_cognito_identity_pool.my_identity_pool.id
          }
          "ForAnyValue:StringLike" = {
            "cognito-identity.amazonaws.com:amr" = "unauthenticated"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "cognito_unauthenticated_policy" {
  name = "cognito_unauthenticated_policy"
  role = aws_iam_role.cognito_unauthenticated_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "mobileanalytics:PutEvents",
          "cognito-sync:GetRecords",
          "cognito-sync:QueryRecords",
          "cognito-sync:SubscribeToDataset",
          "cognito-sync:UnsubscribeFromDataset",
          "cognito-sync:UpdateRecords"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_cognito_identity_pool_roles_attachment" "identity_pool_roles_attachment" {
  identity_pool_id = aws_cognito_identity_pool.my_identity_pool.id
  roles = {
    authenticated   = aws_iam_role.cognito_authenticated_role.arn
    unauthenticated = aws_iam_role.cognito_unauthenticated_role.arn
  }
}
