}

data "aws_ami" "ubuntu" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["*ubuntu-noble-24.04-amd64-server-*"]
  }
}

resource "aws_security_group" "instance-sg" {
  name = "instance-sg"
  vpc_id = module.vpc.vpc_id
}

resource "aws_vpc_security_group_ingress_rule" "instance-sg-ingress-rule" {
  from_port       = 80
  to_port         = 80
  ip_protocol     = "tcp"
  referenced_security_group_id = aws_security_group.lb-sg.id
  security_group_id = aws_security_group.instance-sg.id
}

resource "aws_vpc_security_group_egress_rule" "instance-sg-egress-rule" {
  from_port       = 0
  to_port         = 0
  ip_protocol     = "-1"
  cidr_ipv4       = "0.0.0.0/0"
  security_group_id = aws_security_group.instance-sg.id
}

resource "aws_security_group" "lb-sg" {
  name = "lb-sg"
  vpc_id = module.vpc.vpc_id
}

resource "aws_vpc_security_group_ingress_rule" "lb-sg-ingress-rule" {
  from_port   = 80
  to_port     = 80
  ip_protocol = "tcp"
  cidr_ipv4   = "0.0.0.0/0"
  security_group_id = aws_security_group.lb-sg.id
}

resource "aws_vpc_security_group_egress_rule" "lb-sg-egress-rule" {
  from_port   = 0
  to_port     = 0
  ip_protocol = "-1"
  cidr_ipv4   = "0.0.0.0/0"
  security_group_id = aws_security_group.lb-sg.id
}


resource "aws_instance" "my_instance" {
  ami           = data.aws_ami.ubuntu.id
  instance_type = "t2.micro"
  subnet_id     = module.vpc.public_subnets[0]
  security_groups = [ aws_security_group.instance-sg.id ]
}

resource "aws_lb" "test" {
  subnets            = module.vpc.public_subnets
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.lb-sg.id]
}

resource "aws_lb_listener" "my_listener" {
  load_balancer_arn = aws_lb.test.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type = "authenticate-oidc"

  authenticate_oidc {
      authorization_endpoint = "https://example.com/authorization_endpoint"
      client_id              = "client_id"
      client_secret          = "client_secret"
      issuer                 = "https://example.com"
      token_endpoint         = "https://example.com/token_endpoint"
      user_info_endpoint     = "https://example.com/user_info_endpoint"
    }
  }

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.target_group.arn
  }
}

resource "aws_lb_target_group" "target_group" {
  port     = 80
  protocol = "HTTP"
  vpc_id   = module.vpc.vpc_id
}

resource "aws_lb_target_group_attachment" "ec2_attach" {
  target_group_arn = aws_lb_target_group.target_group.arn
  target_id = aws_instance.my_instance.id
}

LLM Output #0:
### Description

This Terraform program creates an Application Load Balancer (ALB) with an Authenticate-OIDC action. It includes the following resources:

1. **AWS Load Balancer (`aws_lb`)**: An Application Load Balancer that routes incoming traffic to target groups.
2. **AWS Load Balancer Listener (`aws_lb_listener`)**: A listener that listens for incoming HTTPS traffic on port 443.
3. **AWS Load Balancer Listener Rule (`aws_lb_listener_rule`)**: A rule that applies an Authenticate-OIDC action to incoming requests.
4. **AWS IAM Role (`aws_iam_role`)**: An IAM role with permissions for OIDC authentication.
5. **AWS IAM Role Policy (`aws_iam_role_policy`)**: A policy attached to the IAM role that allows OIDC authentication.
6. **AWS Load Balancer Target Group (`aws_lb_target_group`)**: A target group that defines the targets (e.g., EC2 instances) for the load balancer.
7. **AWS Load Balancer Target Group Attachment (`aws_lb_target_group_attachment`)**: An attachment that associates targets with the target group.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_lb" "my_load_balancer" {
  name               = "my-alb"
  internal           = false
  load_balancer_type = "application"
  security_groups    = ["sg-0123456789abcdef0"]  # Replace with your security group ID
  subnets            = ["subnet-0123456789abcdef0", "subnet-0123456789abcdef1"]  # Replace with your subnet IDs

  access_logs {
    bucket = "my-alb-logs-bucket"  # Replace with your S3 bucket name
    prefix = "alb-logs/"
    enabled = true
  }
}

resource "aws_lb_listener" "my_listener" {
  load_balancer_arn = aws_lb.my_load_balancer.arn
  port              = "443"
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS-1-2-Ext-2018-06"
  certificate_arn   = "arn:aws:acm:us-west-2:123456789012:certificate/12345678-1234-1234-1234-123456789012"  # Replace with your ACM certificate ARN

  default_action {
    type             = "fixed-response"
    fixed_response {
      content_type = "text/plain"
      message_body = "Fixed response content"
      status_code  = "200"
    }
  }
}

resource "aws_lb_listener_rule" "my_listener_rule" {
  listener_arn = aws_lb_listener.my_listener.arn
  priority     = 1

  action {
    type = "authenticate-oidc"

    authenticate_oidc {
      authorization_endpoint = "https://example.com/auth"  # Replace with your OIDC provider's authorization endpoint
      client_id              = "your-client-id"          # Replace with your OIDC client ID
      client_secret          = "your-client-secret"      # Replace with your OIDC client secret
      issuer                 = "https://example.com"      # Replace with your OIDC provider's issuer URL
      token_endpoint         = "https://example.com/token" # Replace with your OIDC provider's token endpoint
      user_info_endpoint     = "https://example.com/userinfo"  # Replace with your OIDC provider's user info endpoint
      session_cookie_name    = "AWSELBAuthSessionCookie"
      session_timeout        = 3600
    }
  }

  condition {
    field  = "host-header"
    values = ["example.com"]  # Replace with your domain
  }
}

resource "aws_iam_role" "oidc_auth_role" {
  name = "oidc-auth-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRoleWithWebIdentity"
        Effect = "Allow"
        Principal = {
          Federated = "cognito-identity.amazonaws.com"
        }
        Condition = {
          StringEquals = {
            "cognito-identity.amazonaws.com:aud" = "your-cognito-pool-id"  # Replace with your Cognito pool ID
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "oidc_auth_policy" {
  name = "oidc-auth-policy"
  role = aws_iam_role.oidc_auth_role.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "cognito-idp:DescribeUserPoolClient",
          "cognito-idp:GetUser",
          "cognito-idp:ListUsers"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_lb_target_group" "my_target_group" {
  name     = "my-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = "vpc-0123456789abcdef0"  # Replace with your VPC ID

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }
}

resource "aws_lb_target_group_attachment" "my_target_group_attachment" {
  target_group_arn = aws_lb_target_group.my_target_group.arn
  target_id        = "i-0123456789abcdef0"  # Replace with your EC2 instance ID
  port             = 80
}
```

### Notes

- Replace placeholder values such as security group IDs, subnet IDs, S3 bucket names, ACM certificate ARNs, OIDC provider URLs, Cognito pool IDs, and EC2 instance IDs with actual values from your AWS account.
- Ensure that the IAM role and policy have the necessary permissions for OIDC authentication.
- The Authenticate-OIDC action requires additional configuration not shown here, such as the OIDC provider and client settings. Adjust the `authenticate_oidc` block accordingly.

