### Description
This Terraform program creates an Application Load Balancer (ALB) and a target group associated with it. The ALB is configured with basic settings such as subnets and security groups. The target group is set up to handle traffic for the ALB.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_lb" "my_application_load_balancer" {
  name               = "my-application-load-balancer"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.lb_sg.id]
  subnets            = [aws_subnet.public[0].id, aws_subnet.public[1].id]

  access_logs {
    bucket = aws_s3_bucket.lb_logs.id
    prefix = "alb-logs/"
    enabled = true
  }

  enable_deletion_protection = true
  tags = {
    Environment = "production"
  }
}

resource "aws_lb_target_group" "my_target_group" {
  name     = "my-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id

  health_check {
    enabled             = true
    interval            = 30
    path                = "/"
    port                = "traffic-port"
    protocol            = "HTTP"
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }

  tags = {
    Environment = "production"
  }
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "public-subnet-${count.index}"
  }
}

data "aws_availability_zones" "available" {}

resource "aws_security_group" "lb_sg" {
  name        = "my-alb-sg"
  description = "Security group for my application load balancer"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "my-alb-sg"
  }
}

resource "aws_s3_bucket" "lb_logs" {
  bucket = "my-alb-logs-bucket"
  acl    = "log-delivery-write"

  tags = {
    Name = "my-alb-logs-bucket"
  }
}
```

This Terraform configuration sets up an Application Load Balancer with a target group. It includes the necessary resources such as a VPC, subnets, security group, and S3 bucket for storing access logs. The load balancer and target group are properly configured to work together.

