LLM Output #0:
### Description
This Terraform configuration creates an Application Load Balancer (ALB) along with a Target Group and attaches a target to the Target Group. The ALB is configured to listen on port 80 and forward traffic to the Target Group. The Target Group is set up to use the HTTP protocol and is associated with a specific VPC.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "public" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)
}

data "aws_availability_zones" "available" {}

resource "aws_lb" "my_application_load_balancer" {
  name               = "my-application-load-balancer"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.lb_sg.id]
  subnets            = aws_subnet.public[*].id

  enable_deletion_protection = true

  access_logs {
    bucket = aws_s3_bucket.lb_logs.id
    prefix = "my-alb-logs/"
    enabled = true
  }

  tags = {
    Environment = "production"
  }
}

resource "aws_security_group" "lb_sg" {
  name        = "my-alb-sg"
  description = "Security group for my application load balancer"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_s3_bucket" "lb_logs" {
  bucket = "my-alb-logs-bucket"
  acl    = "log-delivery-write"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lb_target_group" "my_alb_target_group" {
  name     = "my-alb-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id

  health_check {
    enabled             = true
    healthy_threshold   = 3
    unhealthy_threshold = 3
    interval            = 30
    timeout             = 5
    path                = "/"
  }

  tags = {
    Environment = "production"
  }
}

resource "aws_alb_target_group_attachment" "my_alb_target_group_attachment" {
  target_group_arn = aws_lb_target_group.my_alb_target_group.arn
  target_id        = "i-1234567890abcdef0"  # Replace with a valid EC2 instance ID
  port             = 80
}
```

### Explanation
- **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
- **VPC and Subnets**: A VPC and two public subnets are created.
- **Security Group**: A security group is created to allow HTTP traffic on port 80.
- **S3 Bucket**: An S3 bucket is created to store access logs for the ALB.
- **Application Load Balancer**: An ALB is created with the specified settings, including access logs and security groups.
- **Target Group**: A Target Group is created to manage the targets for the ALB.
- **Target Group Attachment**: A target (EC2 instance) is attached to the Target Group. Replace `"i-1234567890abcdef0"` with a valid EC2 instance ID.

