LLM Output #0:
### Description
This Terraform configuration sets up an AWS Aurora MySQL database cluster with a primary instance and a read replica. It includes the necessary IAM roles and policies for replication, as well as subnet groups and security groups to ensure proper network access.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Subnet groups for primary and replica clusters
resource "aws_db_subnet_group" "primary_subnet_group" {
  name       = "primary-subnet-group"
  subnet_ids = ["subnet-0123456789abcdef0", "subnet-0fedcba9876543210"]
}

resource "aws_db_subnet_group" "replica_subnet_group" {
  name       = "replica-subnet-group"
  subnet_ids = ["subnet-0123456789abcdef1", "subnet-0fedcba9876543211"]
}

# Security groups for primary and replica clusters
resource "aws_security_group" "primary_sg" {
  name        = "primary-sg"
  description = "Security group for primary SQL cluster"
  vpc_id      = "vpc-0123456789abcdef0"

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_security_group" "replica_sg" {
  name        = "replica-sg"
  description = "Security group for replica SQL cluster"
  vpc_id      = "vpc-0123456789abcdef0"

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# IAM role and policy for RDS replication
resource "aws_iam_role" "rds_replication_role" {
  name = "rds-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "rds_replication_policy" {
  name        = "rds-replication-policy"
  description = "Policy for RDS replication"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "rds:DescribeDBClusters",
          "rds:DescribeDBClusterSnapshots",
          "rds:DescribeDBInstances",
          "rds:DescribePendingMaintenanceActions",
          "rds:ListTagsForResource",
          "rds:ModifyDBInstance",
          "rds:PromoteReadReplicaDBCluster",
          "rds:StartDBCluster",
          "rds:StopDBCluster"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_rds_replication_policy" {
  policy_arn = aws_iam_policy.rds_replication_policy.arn
  role       = aws_iam_role.rds_replication_role.name
}

# Primary RDS cluster and instance
resource "aws_rds_cluster" "primary_sql_cluster" {
  engine              = "aurora-mysql"
  engine_version      = "8.0.mysql_aurora.3.02.0"
  cluster_identifier  = "primary-cluster"
  master_username     = "admin"
  master_password     = "password123"
  backup_retention_period = 5
  preferred_backup_window = "07:00-09:00"
  db_subnet_group_name = aws_db_subnet_group.primary_subnet_group.name
  vpc_security_group_ids = [aws_security_group.primary_sg.id]
}

resource "aws_rds_cluster_instance" "primary_sql_instance" {
  cluster_identifier    = aws_rds_cluster.primary_sql_cluster.cluster_identifier
  engine                = aws_rds_cluster.primary_sql_cluster.engine
  instance_class        = "db.t3.medium"
  db_subnet_group_name  = aws_db_subnet_group.primary_subnet_group.name
  db_parameter_group_name = "default.aurora-mysql8.0"
  publicly_accessible = false
}

# Replica RDS cluster and instance
resource "aws_rds_cluster" "replica_sql_cluster" {
  engine              = "aurora-mysql"
  engine_version      = aws_rds_cluster.primary_sql_cluster.engine_version
  cluster_identifier  = "replica-cluster"
  replication_source_identifier = aws_rds_cluster.primary_sql_cluster.cluster_identifier
  db_subnet_group_name = aws_db_subnet_group.replica_subnet_group.name
  vpc_security_group_ids = [aws_security_group.replica_sg.id]
  iam_database_authentication_enabled = true
  iam_roles             = [aws_iam_role.rds_replication_role.arn]
}

resource "aws_rds_cluster_instance" "replica_sql_instance" {
  cluster_identifier    = aws_rds_cluster.replica_sql_cluster.cluster_identifier
  engine                = aws_rds_cluster.replica_sql_cluster.engine
  instance_class        = "db.t3.medium"
  db_subnet_group_name  = aws_db_subnet_group.replica_subnet_group.name
  db_parameter_group_name = "default.aurora-mysql8.0"
  publicly_accessible = false
}
```

This Terraform configuration creates an Aurora MySQL primary cluster and a read replica cluster, along with the necessary IAM roles and policies for replication. The primary and replica clusters are configured with their respective subnet groups and security groups to ensure proper network access.

