### Description
This Terraform program creates an AWS EFS (Elastic File System) with a system policy. It includes the following resources:
1. **AWS EFS File System**: A basic EFS file system.
2. **IAM Role**: An IAM role that will be associated with the EFS access point.
3. **IAM Policy**: A custom IAM policy that defines the permissions for the EFS system.
4. **IAM Role Policy Attachment**: Attaches the custom IAM policy to the IAM role.
5. **AWS EFS Access Point**: An EFS access point that uses the IAM role for access control.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

resource "aws_efs_file_system" "efs_file_system" {
  creation_token = "my-efs-file-system"
  encrypted      = true
}

resource "aws_iam_role" "efs_system_policy_role" {
  name = "efs-system-policy-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "efs_system_policy" {
  name        = "efs-system-policy"
  description = "Policy for EFS system access"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "elasticfilesystem:ClientMount",
          "elasticfilesystem:ClientWrite",
          "elasticfilesystem:ClientRootAccess"
        ]
        Effect   = "Allow"
        Resource = aws_efs_file_system.efs_file_system.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_efs_system_policy_to_role" {
  policy_arn = aws_iam_policy.efs_system_policy.arn
  role       = aws_iam_role.efs_system_policy_role.name
}

resource "aws_efs_access_point" "efs_access_point" {
  file_system_id = aws_efs_file_system.efs_file_system.id

  root_directory {
    path = "/"
  }

  posix_user {
    uid     = 1000
    gid     = 1000
    secondary_gids = ["1001", "1002"]
  }
}
```

### Explanation
- **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region. You can change this to your preferred region.
- **EFS File System**: A basic EFS file system is created with encryption enabled.
- **IAM Role**: An IAM role named `efs-system-policy-role` is created with an assume role policy that allows EC2 instances to assume this role.
- **IAM Policy**: A custom IAM policy named `efs-system-policy` is created, granting permissions for client mount, write, and root access to the EFS file system.
- **IAM Role Policy Attachment**: The custom IAM policy is attached to the IAM role.
- **EFS Access Point**: An EFS access point is created, using the IAM role for access control. The root directory is set to `/`, and a POSIX user with specific UID, GID, and secondary GIDs is configured.

