### Description
This Terraform program configures AWS as the cloud provider and defines an AWS VPC with a specific CIDR block of `10.0.0.0/16`. It also sets up a network ACL linked to this VPC with specific ingress and egress rules allowing TCP traffic on port 80 for ingress and port 443 for egress from the CIDR block `10.3.0.0/18`.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Specify a valid AWS region
}

resource "aws_vpc" "main_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "MainVPC"
  }
}

resource "aws_network_acl" "main_network_acl" {
  vpc_id = aws_vpc.main_vpc.id

  ingress {
    rule_no   = 100
    action    = "allow"
    protocol  = "tcp"
    from_port = 80
    to_port   = 80
    cidr_block = "10.3.0.0/18"
  }

  egress {
    rule_no   = 200
    action    = "allow"
    protocol  = "tcp"
    from_port = 443
    to_port   = 443
    cidr_block = "10.3.0.0/18"
  }

  tags = {
    Name = "MainNetworkACL"
  }
}
```

This configuration creates a VPC with the specified CIDR block and a network ACL that allows the specified TCP traffic rules. The network ACL is associated with the VPC through the `vpc_id` attribute.

